var e={"a-042555":{slug:`a-042555`,birthDeath:`1919.10.22 — 2013.11.17`,nationality:`英国`,englishName:`DORIS LESSING`,movement:[`现实主义`,`心理小说`,`思辨小说`],bio:[`生于波斯克尔曼沙赫的英国职员家庭，五岁随家迁往南罗得西亚农场，少年辍学，做过护士、电话员与记者。非洲殖民地的种族裂痕与女性处境，成为她最早的写作材料。`,`一九五〇年以《野草在歌唱》进入文坛，随后用《暴力的孩子们》五部曲追踪女主人公玛莎从殖民地到伦敦的政治与情感觉醒，现实主义笔法逐步让位于心理剖析。`,`《金色笔记》以四本笔记加一部总笔记的拼贴结构拆解女性写作与政治信仰；七十年代转向《什卡斯塔》等太空寓言，晚期又以《第五个孩子》《裂缝》重返家庭与性别议题，形式跨度极大。`],controversies:[{tag:`女性主义标签之争`,content:`她多次拒绝女性主义偶像的定位，称《金色笔记》并非妇女解放的纲领，引发与部分女性主义批评者的长期龃龉。`}],works:[{year:`1950`,title:`《野草在歌唱》`,type:`长篇小说`,note:`殖民地种族裂痕的处女作`},{year:`1952`,title:`《玛莎·奎斯特》`,type:`长篇小说`,note:`五部曲开篇的少女成长`},{year:`1962`,title:`《金色笔记》`,type:`长篇小说`,note:`笔记拼贴的女性主义经典`},{year:`1969`,title:`《四门之城》`,type:`长篇小说`,note:`五部曲终卷的末世伦敦`},{year:`1974`,title:`《幸存者回忆录》`,type:`长篇小说`,note:`灾难后的城市寓言，可见其创作脉络`},{year:`1979`,title:`《什卡斯塔》`,type:`长篇小说`,note:`太空思辨系列的首部，风格印记鲜明`},{year:`1988`,title:`《第五个孩子》`,type:`长篇小说`,note:`家庭内部的异类恐惧，值得细读`},{year:`1996`,title:`《又来了，爱情》`,type:`长篇小说`,note:`老年女性的情欲与舞台`},{year:`2007`,title:`《裂缝》`,type:`长篇小说`,note:`史前性别秩序的寓言，可见其创作脉络`}],position:`她把殖民地经验、女性意识与左翼政治放进不断变换的小说形式中，从现实主义到太空寓言均留下实验痕迹，是二战后英语文学最不愿被归类的长跑者。`,positionSource:`— 诺贝尔文学奖授奖辞`,nobelYear:2007},"a-c406ac":{slug:`a-c406ac`,birthDeath:`1947.06.19 —`,nationality:`英国/印度裔`,englishName:`SALMAN RUSHDIE`,movement:[`后现代主义`,`魔幻现实主义`,`印度英语文学`],bio:[`生于孟买一个说乌尔都语的穆斯林商人家庭，十四岁赴英求学，后在广告业任职。早期《格里姆斯》混合科幻与神话，尚未找到后来标志性的印度叙事声音。`,`《午夜之子》借独立时刻出生的孩子把印度现代史写成魔幻家史，获布克奖；《羞耻》以寓言笔法处理巴基斯坦政治，确立其戏仿、杂糅与狂欢化的独特文体。`,`《撒旦诗篇》引发全球追杀令，他长期受警方保护；此后《哈伦与故事海》《摩尔人的最后叹息》继续在移民、信仰与叙事自由之间展开，回忆录《约瑟夫·安东》记录那段隐匿岁月。`],controversies:[{tag:`撒旦诗篇追杀令`,content:`一九八八年《撒旦诗篇》被指亵渎伊斯兰教，伊朗最高领袖霍梅尼发布追杀令，多国出现抗议与暴力事件，翻译出版者亦受袭击。`},{tag:`遇刺事件`,content:`二〇二二年他在纽约州演讲时遭持刀袭击，右眼失明，事件再度引发关于言论自由与宗教极端主义的争论。`}],works:[{year:`1975`,title:`《格里姆斯》`,type:`长篇小说`,note:`科幻与神话混合的早期实验`},{year:`1981`,title:`《午夜之子》`,type:`长篇小说`,note:`印度现代史的魔幻家史`},{year:`1983`,title:`《羞耻》`,type:`长篇小说`,note:`巴基斯坦政治的寓言书写`},{year:`1988`,title:`《撒旦诗篇》`,type:`长篇小说`,note:`引发全球争议的宗教寓言`},{year:`1990`,title:`《哈伦与故事海》`,type:`长篇小说`,note:`献给儿子的叙事童话，风格印记鲜明`},{year:`1995`,title:`《摩尔人的最后叹息》`,type:`长篇小说`,note:`孟买家族的衰败史诗，值得细读`},{year:`1999`,title:`《她脚下的土地》`,type:`长篇小说`,note:`流行音乐与神话的重写`},{year:`2005`,title:`《小丑沙利马》`,type:`长篇小说`,note:`克什米尔与恐怖主义题材`},{year:`2012`,title:`《约瑟夫·安东》`,type:`回忆录`,note:`追杀令下的隐匿岁月，可见其创作脉络`},{year:`2024`,title:`《刀》`,type:`回忆录`,note:`遇刺后的康复与反思，风格印记鲜明`}],position:`他以魔幻、戏仿与移民经验重写印度现代史，把后殖民英语小说推向国际舞台；围绕《撒旦诗篇》的冲突，也使文学自由与宗教敏感的边界成为全球议题。`,positionSource:`— 布克奖评语`,nobelYear:null},"a-de1af3":{slug:`a-de1af3`,birthDeath:`1954.11.08 —`,nationality:`英国/日裔`,englishName:`KAZUO ISHIGURO`,movement:[`国际主义小说`,`不可靠叙述`,`记忆小说`],bio:[`生于长崎，五岁随父母移居英国，在肯特与萨里长大。东英吉利大学写作课程期间师从安吉拉·卡特，早期作品多以战后日本为背景，语调克制而含混。`,`《远山淡影》《浮世画家》借回忆与自我辩解揭开战争阴影；《长日将尽》以管家独白把帝国衰落与个人压抑并置，获布克奖，确立不可靠叙述者的核心手法。`,`《无法安慰的人》转向梦境般的欧洲城市，《别让我走》《克拉拉与太阳》以克隆人与人工智能审视爱与牺牲；他自称国际主义作家，题材跨越国界而始终保持第一人称的哀悼语气。`],controversies:[{tag:`国际主义身份讨论`,content:`他自称国际主义作家，刻意淡化日裔背景，评论界因此长期争论其作品究竟属于英国文学、日本文学还是跨国市场塑造的世界文学。`}],works:[{year:`1982`,title:`《远山淡影》`,type:`长篇小说`,note:`战后长崎的回忆与回避`},{year:`1986`,title:`《浮世画家》`,type:`长篇小说`,note:`战前画家的事后辩解，值得细读`},{year:`1989`,title:`《长日将尽》`,type:`长篇小说`,note:`管家独白与帝国黄昏，可见其创作脉络`},{year:`1995`,title:`《无法安慰的人》`,type:`长篇小说`,note:`梦境结构的欧洲城市，风格印记鲜明`},{year:`2000`,title:`《我辈孤雏》`,type:`长篇小说`,note:`上海租界的侦探回忆，值得细读`},{year:`2005`,title:`《别让我走》`,type:`长篇小说`,note:`克隆人学校的青春与捐献`},{year:`2015`,title:`《被掩埋的巨人》`,type:`长篇小说`,note:`亚瑟王时代的记忆迷雾`},{year:`2021`,title:`《克拉拉与太阳》`,type:`长篇小说`,note:`人工智能的观察与信仰`}],position:`他以克制的第一人称与不可靠回忆，书写帝国余晖、克隆人与人工智能的伦理困境；跨文化题材使其成为当代英语世界最受学院与大众同时阅读的小说家之一。`,positionSource:`— 诺贝尔文学奖授奖辞`,nobelYear:2017},"a-ea0275":{slug:`a-ea0275`,birthDeath:`1948.06.21 —`,nationality:`英国`,englishName:`IAN MCEWAN`,movement:[`心理现实主义`,`道德小说`,`科学叙事`],bio:[`生于奥尔德肖特军人家庭，童年在利比亚与新加坡度过。东英吉利大学写作班出身，早期《水泥花园》《陌生人的慰藉》以畸恋、暴力与封闭空间获恐怖伊恩之名。`,`八十年代起由心理惊悚转向社会政治与家庭伦理，《时间中的孩子》处理失子之痛与育儿政策，《阿姆斯特丹》以安乐死讽刺英国文人圈的虚伪并获布克奖。`,`《赎罪》用元小说式反转讨论叙事能否赎罪，《星期六》《追日》延伸到伊拉克战争与气候危机；近作《像我这样的机器》《教训》继续把技术伦理与历史记忆编织进个人生活。`],controversies:[],works:[{year:`1978`,title:`《水泥花园》`,type:`长篇小说`,note:`封闭家庭的畸恋寓言，可见其创作脉络`},{year:`1981`,title:`《陌生人的慰藉》`,type:`长篇小说`,note:`威尼斯旅行的暴力阴影`},{year:`1987`,title:`《时间中的孩子》`,type:`长篇小说`,note:`失子之痛与育儿政治，风格印记鲜明`},{year:`1998`,title:`《阿姆斯特丹》`,type:`长篇小说`,note:`安乐死讽刺与布克奖，值得细读`},{year:`2001`,title:`《赎罪》`,type:`长篇小说`,note:`元小说反转与战争创伤`},{year:`2005`,title:`《星期六》`,type:`长篇小说`,note:`伊拉克战争阴影下的一天`},{year:`2010`,title:`《追日》`,type:`长篇小说`,note:`气候科学与中年危机，可见其创作脉络`},{year:`2019`,title:`《像我这样的机器》`,type:`长篇小说`,note:`人工智能与替代伦理，风格印记鲜明`},{year:`2022`,title:`《教训》`,type:`长篇小说`,note:`历史巨变中的个人一生`}],position:`他从哥特式心理惊悚起步，逐步把科学、政治与家庭伦理纳入精密叙事，被视为当代英国最擅长处理道德困境与历史创伤的小说家之一。`,nobelYear:null},"a-735b31":{slug:`a-735b31`,birthDeath:`1946.01.19 —`,nationality:`英国`,englishName:`JULIAN BARNES`,movement:[`后现代主义`,`历史小说`,`元小说`],bio:[`生于莱斯特，父母皆为法语教师，牛津毕业后为《新政治家》等刊物撰写评论并开始尝试小说创作。首作《都市地铁》以成长与比较文化为题，仍属传统叙事。`,`《福楼拜的鹦鹉》把传记、佚事与自传拼成关于福楼拜的论文式小说，《10½章世界史》以木蠹的旁白重写历史，确立其怀疑主义与形式游戏的独特叙事风格。`,`《英格兰，英格兰》以主题公园复制不列颠，《终结的感觉》借不可靠回忆追问时间与责任，获布克奖；晚近《唯一的故事》《伊丽莎白·芬奇》转向爱情与思想传记的静默书写。`],controversies:[],works:[{year:`1980`,title:`《都市地铁》`,type:`长篇小说`,note:`成长与英法文化对照，值得细读`},{year:`1984`,title:`《福楼拜的鹦鹉》`,type:`长篇小说`,note:`传记与虚构的论文式拼贴`},{year:`1989`,title:`《10½章世界史》`,type:`长篇小说`,note:`木蠹旁白重写人类历史`},{year:`1992`,title:`《猪》`,type:`长篇小说`,note:`东欧转型期的政治寓言`},{year:`1998`,title:`《英格兰，英格兰》`,type:`长篇小说`,note:`主题公园复制民族记忆`},{year:`2005`,title:`《亚瑟与乔治》`,type:`长篇小说`,note:`真实案件的种族与司法`},{year:`2011`,title:`《终结的感觉》`,type:`长篇小说`,note:`不可靠回忆与时间责任`},{year:`2018`,title:`《唯一的故事》`,type:`长篇小说`,note:`一段恋情的多种版本，可见其创作脉络`},{year:`2022`,title:`《伊丽莎白·芬奇》`,type:`长篇小说`,note:`思想传记与晚期爱情，风格印记鲜明`}],position:`他以怀疑主义与形式游戏拆解传记、历史与记忆的可靠性，在短小篇幅中容纳大量思辨，是英国后现代小说中最具随笔气质的一位。`,nobelYear:null},"a-63a0f9":{slug:`a-63a0f9`,birthDeath:`1952.07.06 — 2022.09.22`,nationality:`英国`,englishName:`HILARY MANTEL`,movement:[`历史小说`,`新历史主义`,`心理现实主义`],bio:[`生于德比郡哈德菲尔德，天主教家庭背景，先后在伦敦政治经济学院与谢菲尔德大学攻读法律。早年《每天都是母亲节》以黑色喜剧写贫困与精神疾病。`,`《更安全的地方》以十二个视角重述法国大革命，显示其对史料与多声部的掌控；长期写作受阻后，她转向都铎王朝，用现在时与自由间接引语重塑历史人物。`,`《狼厅》《提堂》《镜与光》三部曲以托马斯·克伦威尔的视角拆解宗教改革与宫廷政治，两度获布克奖；回忆录《放弃幽灵》则记录童年与写作的创伤根源与创作起点。`],controversies:[{tag:`历史翻案争议`,content:`《狼厅》以克伦威尔的同情视角重写都铎宫廷，弱化托马斯·莫尔的殉道形象，受到部分天主教评论者的历史翻案指责。`}],works:[{year:`1985`,title:`《每天都是母亲节》`,type:`长篇小说`,note:`黑色喜剧中的贫困与疯癫`},{year:`1992`,title:`《更安全的地方》`,type:`长篇小说`,note:`法国大革命的多声部重述`},{year:`1994`,title:`《气候变迁》`,type:`长篇小说`,note:`家庭秘密与道德责任，值得细读`},{year:`2003`,title:`《放弃幽灵》`,type:`回忆录`,note:`童年创伤与写作起源，可见其创作脉络`},{year:`2009`,title:`《狼厅》`,type:`长篇小说`,note:`克伦威尔视角的都铎宫廷`},{year:`2012`,title:`《提堂》`,type:`长篇小说`,note:`安妮·博林案的权力绞杀`},{year:`2020`,title:`《镜与光》`,type:`长篇小说`,note:`三部曲终卷的衰败与处决`}],position:`她把历史小说从复原式叙事推向语言与视角的实验，以克伦威尔三部曲重画都铎政治版图，被视为二十一世纪英语历史写作的标杆。`,nobelYear:null},"a-2a73a8":{slug:`a-2a73a8`,birthDeath:`1949.08.25 — 2023.05.19`,nationality:`英国`,englishName:`MARTIN AMIS`,movement:[`后现代主义`,`黑色幽默`,`伦敦文学`],bio:[`生于牛津，父亲是小说家金斯利·艾米斯。牛津大学埃克塞特学院毕业后最初任《泰晤士报文学增刊》编辑，早期以青春、性爱与消费文化为题材，语气尖刻。`,`《金钱》以广告人塞尔夫的自述写撒切尔时代的贪婪与肥胖，《伦敦田野》把城市末日、阶层分化与性政治揉成鲜明的黑色喜剧风格，句式繁复而节奏凌厉。`,`《时间之箭》倒叙纳粹医生的逃亡，《兴趣地带》以集中营旁的日常生活写平庸之恶；晚年回忆录《内幕》混合文坛轶事与个人死亡意识，二〇二三年病逝于美国。`],controversies:[{tag:`公共言论争议`,content:`二〇〇六年他公开表示英国穆斯林社群应受到更严厉对待，言论被指为伊斯兰恐惧症，引发广泛批评，此后多次访谈仍反复提及。`}],works:[{year:`1973`,title:`《雷切尔文件》`,type:`长篇小说`,note:`青春焦虑与性爱自白，风格印记鲜明`},{year:`1975`,title:`《死婴》`,type:`长篇小说`,note:`黑色喜剧中的道德溃败`},{year:`1984`,title:`《金钱》`,type:`长篇小说`,note:`撒切尔时代的贪婪史诗`},{year:`1989`,title:`《伦敦田野》`,type:`长篇小说`,note:`城市末日与性政治喜剧`},{year:`1991`,title:`《时间之箭》`,type:`长篇小说`,note:`倒叙纳粹医生的逃亡，值得细读`},{year:`1995`,title:`《信息》`,type:`长篇小说`,note:`文坛嫉妒与复仇叙事，可见其创作脉络`},{year:`2000`,title:`《经历》`,type:`回忆录`,note:`家庭、牙齿与文坛记忆，可见其创作脉络`},{year:`2014`,title:`《兴趣地带》`,type:`长篇小说`,note:`集中营旁的平庸之恶，风格印记鲜明`},{year:`2020`,title:`《内幕》`,type:`回忆录`,note:`文坛轶事与死亡意识，值得细读`}],position:`他以凌厉句法和黑色幽默解剖消费社会、男性焦虑与历史暴力，被视为英国当代后现代小说最喧闹也最自觉的文体家之一。`,nobelYear:null},"a-25635b":{slug:`a-25635b`,birthDeath:`1959.08.27 —`,nationality:`英国`,englishName:`JEANETTE WINTERSON`,movement:[`后现代主义`,`女性主义写作`,`历史改写`],bio:[`生于曼彻斯特，被一对五旬节派夫妇收养，在严格的宗教环境中长大，后离家就读牛津大学。养母与教会对她的压制，成为回忆录与小说的反复主题。`,`《橘子不是唯一的水果》以成长小说写同性恋少女与教会的冲突，《激情》把拿破仑战争与威尼斯赌徒并置，《给樱桃以性别》则重写历史与童话中的女性。`,`《写在身体上》以第二人称写缺席的爱人，《石神》转向科幻与生态寓言；回忆录《正常就好，何必快乐》重述创伤，晚近《弗兰基斯坦》把人工智能与性别议题接续到哥特传统。`],controversies:[],works:[{year:`1985`,title:`《橘子不是唯一的水果》`,type:`长篇小说`,note:`宗教家庭中的同性恋成长`},{year:`1987`,title:`《激情》`,type:`长篇小说`,note:`拿破仑战争与威尼斯赌局`},{year:`1989`,title:`《给樱桃以性别》`,type:`长篇小说`,note:`历史与童话的女性重写`},{year:`1992`,title:`《写在身体上》`,type:`长篇小说`,note:`第二人称的欲望与缺席`},{year:`2000`,title:`《权力之书》`,type:`长篇小说`,note:`电子时代的叙事游戏，可见其创作脉络`},{year:`2007`,title:`《石神》`,type:`长篇小说`,note:`科幻框架下的生态寓言`},{year:`2011`,title:`《正常就好，何必快乐》`,type:`回忆录`,note:`收养家庭与创伤记忆，风格印记鲜明`},{year:`2015`,title:`《时间之间》`,type:`长篇小说`,note:`莎剧冬天的故事改写，值得细读`},{year:`2019`,title:`《弗兰基斯坦》`,type:`长篇小说`,note:`人工智能与性别哥特，可见其创作脉络`}],position:`她把性别、欲望与宗教压抑写进童话、历史与科幻的混杂形式，语言华丽而具论辩性，是英国当代最具公众影响力的女性主义小说家之一。`,nobelYear:null},"a-02a933":{slug:`a-02a933`,birthDeath:`1975.10.25 —`,nationality:`英国`,englishName:`ZADIE SMITH`,movement:[`多文化伦敦小说`,`后现代主义`,`随笔写作`],bio:[`生于伦敦西北部，母亲是牙买加移民，父亲为英国白人。剑桥大学英语系毕业后即凭《白牙》成名，作品多聚焦多族裔都市中的复杂身份、阶级与代际冲突。`,`《白牙》以三个家庭的纠缠写伦敦多元文化的喜剧与暴力，《签名收藏家》转向名人崇拜，《论美》则借校园政治与家庭伦理重写福斯特式的道德小说经典。`,`《西北》以碎片化章节写同一街区的阶层流动，《摇摆时代》回望舞蹈与种族记忆；随笔集《改变我的思想》《感受自由》显示其批评才能，近作《欺诈》转向维多利亚时代的历史小说。`],controversies:[],works:[{year:`2000`,title:`《白牙》`,type:`长篇小说`,note:`多族裔伦敦的家庭喜剧`},{year:`2002`,title:`《签名收藏家》`,type:`长篇小说`,note:`名人崇拜与身份焦虑，风格印记鲜明`},{year:`2005`,title:`《论美》`,type:`长篇小说`,note:`校园政治与福斯特式伦理`},{year:`2009`,title:`《改变我的思想》`,type:`随笔集`,note:`文学、电影与身份评论，风格印记鲜明`},{year:`2012`,title:`《西北》`,type:`长篇小说`,note:`又译《身体边缘》，街区叙事`},{year:`2016`,title:`《摇摆时代》`,type:`长篇小说`,note:`舞蹈、种族与时间记忆，值得细读`},{year:`2018`,title:`《感受自由》`,type:`随笔集`,note:`公共议题与阅读笔记，值得细读`},{year:`2023`,title:`《欺诈》`,type:`长篇小说`,note:`维多利亚时代的真假叙事`}],position:`她以多族裔都市的喜剧笔法处理身份、阶级与文化挪用，又不断以随笔介入公共争论，被视为二十一世纪英国小说中最能回应当下的一位。`,nobelYear:null},"a-457a2d":{slug:`a-457a2d`,birthDeath:`1930.10.10 — 2008.12.24`,nationality:`英国`,englishName:`HAROLD PINTER`,movement:[`荒诞派戏剧`,`威胁喜剧`,`政治戏剧`],bio:[`生于伦敦哈克尼区一个犹太裁缝家庭，二战期间经历疏散与空袭。早年以演员身份跑码头剧团，写诗与广播剧，戏剧语言来自市井口语与长时间停顿。`,`《房间》《生日派对》以封闭空间与莫名威胁确立威胁喜剧，《看门人》把三个流浪者的权力游戏写得既滑稽又残酷，《归家》则以家庭内部的性政治震动观众。`,`七十年代后作品更短、更政治化，《山地语言》《灰烬至灰烬》直指制度性国家暴力；二〇〇五年获诺贝尔文学奖，授奖辞称其揭示日常闲谈背后的巨大历史深渊。`],controversies:[{tag:`政治言论争议`,content:`他强烈反对伊拉克战争，称美国政策为国家恐怖主义，并拒绝在政治立场上妥协，相关言论在英美媒体引发持续批评。`}],works:[{year:`1957`,title:`《房间》`,type:`戏剧`,note:`封闭空间中的莫名威胁`},{year:`1958`,title:`《生日派对》`,type:`戏剧`,note:`威胁喜剧的奠基之作，可见其创作脉络`},{year:`1960`,title:`《看门人》`,type:`戏剧`,note:`三人权力游戏的残酷喜剧`},{year:`1965`,title:`《归家》`,type:`戏剧`,note:`家庭内部的性政治风暴`},{year:`1971`,title:`《旧日》`,type:`戏剧`,note:`记忆与三角关系的暧昧`},{year:`1975`,title:`《无人之地》`,type:`戏剧`,note:`文人晚年的权力与遗忘`},{year:`1978`,title:`《背叛》`,type:`戏剧`,note:`倒叙的婚外情与友谊，风格印记鲜明`},{year:`1988`,title:`《山地语言》`,type:`戏剧`,note:`国家暴力与语言压迫，值得细读`},{year:`1996`,title:`《灰烬至灰烬》`,type:`戏剧`,note:`回忆与暴力的双人剧，可见其创作脉络`}],position:`他把日常对话的停顿变成戏剧张力，用封闭房间与含糊威胁揭示权力、性与记忆的暗流，是二战后英国戏剧最具国际影响的作家之一。`,positionSource:`— 诺贝尔文学奖授奖辞`,nobelYear:2005},"a-df297e":{slug:`a-df297e`,birthDeath:`1937.07.03 —`,nationality:`英国/捷克裔`,englishName:`TOM STOPPARD`,movement:[`荒诞派戏剧`,`知识分子喜剧`,`元戏剧`],bio:[`生于捷克斯洛伐克兹林，纳粹入侵前随家逃往新加坡，父亲在日军占领期间遇难。母亲改嫁英国军官后迁居英格兰，他十七岁辍学，在布里斯托做记者与剧评人。`,`《罗森克兰茨和吉尔登斯特恩已死》让莎剧中的两名次要人物承担存在主义式对话，一举成名；《跳跃者》《怪诞的效仿》把尖锐哲学、政治与杂耍式笑料并置。`,`《阿卡迪亚》在乡村庄园里把混沌数学与浪漫派诗歌交织，《爱的发明》写古典学者的情感，《乌托邦海岸》三部曲处理俄国革命一代；晚年《利奥波德城》回望家族在大屠杀中的命运。`],controversies:[],works:[{year:`1966`,title:`《罗森克兰茨和吉尔登斯特恩已死》`,type:`戏剧`,note:`莎剧配角的存在主义重构`},{year:`1968`,title:`《真正的猎犬探长》`,type:`戏剧`,note:`侦探剧程式的滑稽拆解`},{year:`1972`,title:`《跳跃者》`,type:`戏剧`,note:`哲学、政治与杂耍的拼贴`},{year:`1974`,title:`《怪诞的效仿》`,type:`戏剧`,note:`达达主义与革命者群像`},{year:`1993`,title:`《阿卡迪亚》`,type:`戏剧`,note:`混沌数学与浪漫派诗歌`},{year:`1997`,title:`《爱的发明》`,type:`戏剧`,note:`古典学者的压抑与深情`},{year:`2002`,title:`《乌托邦海岸》`,type:`戏剧`,note:`俄国革命一代的三部曲`},{year:`2006`,title:`《摇滚》`,type:`戏剧`,note:`布拉格之春与摇滚政治`},{year:`2019`,title:`《利奥波德城》`,type:`戏剧`,note:`家族在大屠杀中的命运`}],position:`他把哲学论辩、科学观念与戏剧笑料熔于一炉，让舞台成为思想实验的场所，是当代英语戏剧中智性密度最高、也最擅长自我拆解的剧作家。`,nobelYear:null},"a-b465cf":{slug:`a-b465cf`,birthDeath:`1969.01.12 —`,nationality:`英国`,englishName:`DAVID MITCHELL`,movement:[`后现代主义`,`结构小说`,`跨类型写作`],bio:[`生于默西塞德郡绍斯波特，肯特大学攻读英美文学，毕业后赴日本教授英语八年。广岛与长崎的旅居经验，后来反复出现在其跨国叙事与结构实验之中。`,`《幽灵代笔》以九个互不相关的故事通过细微线索串联，《九号梦》写东京青年的网络与梦境；《云图》用六个嵌套的时空与不同文体，把个体反抗与文明循环拼成整体。`,`《雅各布·德佐特的千秋》转向江户时代的长崎，《骨钟》与《斯雷德屋》引入超自然体系，晚近《乌托邦大道》以乐队兴衰写六十年代；结构游戏始终服务于对权力与记忆的追问。`],controversies:[],works:[{year:`1999`,title:`《幽灵代笔》`,type:`长篇小说`,note:`九个故事以线索串联，风格印记鲜明`},{year:`2001`,title:`《九号梦》`,type:`长篇小说`,note:`东京青年的网络与梦境`},{year:`2004`,title:`《云图》`,type:`长篇小说`,note:`六个时空的嵌套叙事，值得细读`},{year:`2006`,title:`《黑天鹅湖》`,type:`长篇小说`,note:`少年口吃的成长回忆，可见其创作脉络`},{year:`2010`,title:`《雅各布·德佐特的千秋》`,type:`长篇小说`,note:`江户长崎的贸易与爱情`},{year:`2014`,title:`《骨钟》`,type:`长篇小说`,note:`超自然体系与文明衰亡`},{year:`2015`,title:`《斯雷德屋》`,type:`长篇小说`,note:`鬼屋故事的结构变奏，风格印记鲜明`},{year:`2020`,title:`《乌托邦大道》`,type:`长篇小说`,note:`六十年代乐队兴衰史，值得细读`}],position:`他以嵌套叙事与文体模仿把全球化的时空压缩进小说，既能写历史冒险也能写超自然寓言，被视为当代英语文学中最精于结构的设计师之一。`,nobelYear:null},"a-753bc3":{slug:`a-753bc3`,birthDeath:`1939.11.18 —`,nationality:`加拿大`,englishName:`MARGARET ATWOOD`,movement:[`女性主义文学`,`加拿大文学`,`推想小说`],bio:[`生于渥太华，父亲是昆虫学家，童年随家庭在魁北克北部野外度过。多伦多大学与哈佛求学期间专攻维多利亚文学，早年以诗集《圆圈游戏》崭露头角。`,`《可食用的女人》写消费社会中的女性身体，《浮现》转向荒野与精神分裂，《淑女奥拉克》以神话与通俗类型混写；《使女的故事》把清教传统与生育政治推成反乌托邦经典。`,`《猫眼》回望少女时代的权力关系，《盲刺客》以嵌套叙事获布克奖；晚年《羚羊与秧鸡》三部曲处理基因工程与生态崩溃，《遗嘱》续写基列国，她同时是公共议题中活跃的评论者。`],controversies:[],works:[{year:`1966`,title:`《圆圈游戏》`,type:`诗集`,note:`早期诗作中的自然与权力`},{year:`1969`,title:`《可食用的女人》`,type:`长篇小说`,note:`消费社会中的女性身体`},{year:`1972`,title:`《浮现》`,type:`长篇小说`,note:`荒野中的性别与精神危机`},{year:`1976`,title:`《淑女奥拉克》`,type:`长篇小说`,note:`神话与通俗类型的混写`},{year:`1985`,title:`《使女的故事》`,type:`长篇小说`,note:`生育政治的反乌托邦经典`},{year:`1988`,title:`《猫眼》`,type:`长篇小说`,note:`少女友谊与权力记忆，可见其创作脉络`},{year:`2000`,title:`《盲刺客》`,type:`长篇小说`,note:`嵌套叙事与历史谎言，风格印记鲜明`},{year:`2003`,title:`《羚羊与秧鸡》`,type:`长篇小说`,note:`基因工程与生态崩溃，值得细读`},{year:`2009`,title:`《洪水之年》`,type:`长篇小说`,note:`末日社群的信仰与幸存`},{year:`2019`,title:`《遗嘱》`,type:`长篇小说`,note:`基列国内部的女性反抗`}],position:`她把女性主义、生态危机与加拿大民族经验写进反乌托邦和推想小说，既能构造制度寓言，也能处理私人记忆，是当代英语世界读者最广的公共知识分子之一。`,nobelYear:null},"a-66a6ea":{slug:`a-66a6ea`,birthDeath:`1931.07.10 — 2024.05.13`,nationality:`加拿大`,englishName:`ALICE MUNRO`,movement:[`当代短篇小说`,`心理现实主义`],bio:[`生于安大略省温厄姆附近的农场，少女时代在乡村与小镇间迁徙，西安大略大学期间开始发表短篇。婚姻与家庭生活并未中断写作，她长期在厨房与育儿间隙完成小说。`,`《快乐影子之舞》获总督奖，《女孩和女人们的生活》以连环短篇写少女成长，《你以为你是谁》用同一人物的不同阶段拆解身份，短篇集逐渐获得长篇式的整体感。`,`此后《木星的卫星》《爱的进程》《公开的秘密》不断精化时间跳跃与留白，《逃离》《亲爱的生活》把女性晚年的失望与妥协写得极为克制；二〇一三年获诺贝尔文学奖。`],controversies:[{tag:`家庭沉默争议`,content:`二〇二四年其女儿安德里亚·斯金纳公开说，她幼年遭继父性侵，母亲知情后仍选择留在婚姻中，引发对门罗生平与作品伦理的重新讨论。`}],works:[{year:`1968`,title:`《快乐影子之舞》`,type:`短篇小说集`,note:`乡村少女视角的成名作`},{year:`1971`,title:`《女孩和女人们的生活》`,type:`短篇小说集`,note:`连环短篇写少女成长，可见其创作脉络`},{year:`1978`,title:`《你以为你是谁》`,type:`短篇小说集`,note:`同一人物的阶段拼图，风格印记鲜明`},{year:`1982`,title:`《木星的卫星》`,type:`短篇小说集`,note:`婚姻与时间跳跃的精密`},{year:`1986`,title:`《爱的进程》`,type:`短篇小说集`,note:`代际情感与叙事留白，值得细读`},{year:`1990`,title:`《我青年时代的朋友》`,type:`短篇小说集`,note:`乡镇女性的隐秘生活，可见其创作脉络`},{year:`1994`,title:`《公开的秘密》`,type:`短篇小说集`,note:`多篇互文的女性命运，风格印记鲜明`},{year:`2001`,title:`《仇恨、友谊、追求、爱情、婚姻》`,type:`短篇小说集`,note:`情感关系的晚期变奏，值得细读`},{year:`2004`,title:`《逃离》`,type:`短篇小说集`,note:`女性出走的未完成，可见其创作脉络`},{year:`2012`,title:`《亲爱的生活》`,type:`短篇小说集`,note:`晚期作品的告别之声，风格印记鲜明`}],position:`她以短篇小说的有限篇幅容纳数十年的婚姻、阶级与女性经验，用时间跳跃和沉默把日常写成命运，被公认为英语短篇传统在当代最重要的继承者。`,positionSource:`— 诺贝尔文学奖授奖辞`,nobelYear:2013},"a-0dd733":{slug:`a-0dd733`,birthDeath:`1950.06.21 —`,nationality:`加拿大`,englishName:`ANNE CARSON`,movement:[`后现代诗歌`,`古典改写`,`抒情散文`],bio:[`生于多伦多，先后在多伦多大学与圣安德鲁斯大学研习古典学，长期教授希腊语与拉丁语。古典诗学与哲学的训练，使她的写作始终在注释、翻译与原创之间游走。`,`《爱欲的苦甜》以论文体讨论古希腊爱情诗，《短谈》用极短的诗性段落写感官与记忆，《玻璃、讽刺与上帝》把圣奥古斯丁、萨福与当代宗教生活并置与对照。`,`《红色自传》以赫拉克勒斯神话重写少年之爱，混合诗、散文与伪学术注释；《丈夫的美》《创造》继续拆解婚姻与神学，长诗《诺克斯》以挽歌形式处理兄长之死，形式实验始终伴随哀悼。`],controversies:[],works:[{year:`1986`,title:`《爱欲的苦甜》`,type:`论著`,note:`古希腊爱情诗的论文体研究`},{year:`1992`,title:`《短谈》`,type:`诗集`,note:`极短段落中的感官记忆`},{year:`1995`,title:`《玻璃、讽刺与上帝》`,type:`诗集`,note:`古典与宗教的并置，值得细读`},{year:`1998`,title:`《红色自传》`,type:`诗体小说`,note:`赫拉克勒斯神话的爱情重写`},{year:`2001`,title:`《丈夫的美》`,type:`诗集`,note:`婚姻、欲望与古典诗学，可见其创作脉络`},{year:`2005`,title:`《创造》`,type:`跨文体作品`,note:`神学、艺术与女性声音，风格印记鲜明`},{year:`2010`,title:`《诺克斯》`,type:`挽歌`,note:`以注释形式悼念兄长，可见其创作脉络`},{year:`2013`,title:`《红文档》`,type:`诗体小说`,note:`红色自传的续篇与衰老`},{year:`2016`,title:`《漂浮》`,type:`诗集`,note:`散页形式的水与记忆，风格印记鲜明`}],position:`她把古典学、翻译与自传熔成难以归类的文体，用注释、残篇和短句制造思想的停顿，是当代英语诗歌中最具智性锋芒也最难以模仿的写作者。`,nobelYear:null},"a-176abf":{slug:`a-176abf`,birthDeath:`1943.09.12 —`,nationality:`加拿大/斯里兰卡裔`,englishName:`MICHAEL ONDAATJE`,movement:[`后殖民文学`,`拼贴叙事`,`诗性小说`],bio:[`生于科伦坡，父亲有印度与荷兰血统，母亲是斯里兰卡人。十一岁赴英格兰求学，十九岁移居加拿大，在多伦多大学与皇后大学完成学业，早年以诗集成名。`,`《比利小子的全集》以诗与档案重写西部亡命徒，《穿过屠宰场》写新奥尔良爵士乐手博尔登的疯狂与死亡，《世代相传》则以家族记忆拼出斯里兰卡殖民史。`,`《狮子皮》写多伦多移民劳工与桥梁建造，《英国病人》以二战沙漠与废墟中的爱情获布克奖；《阿尼尔的幽灵》转向斯里兰卡内战，《猫桌》《战争之光》继续在记忆与帝国阴影中航行。`],controversies:[],works:[{year:`1967`,title:`《优雅的怪物》`,type:`诗集`,note:`早期诗作中的异乡感官`},{year:`1970`,title:`《比利小子的全集》`,type:`长诗`,note:`西部亡命徒的诗体档案`},{year:`1976`,title:`《穿过屠宰场》`,type:`长篇小说`,note:`爵士乐手的疯狂与死亡`},{year:`1982`,title:`《世代相传》`,type:`回忆录`,note:`家族记忆中的斯里兰卡`},{year:`1987`,title:`《狮子皮》`,type:`长篇小说`,note:`多伦多移民与桥梁劳工`},{year:`1992`,title:`《英国病人》`,type:`长篇小说`,note:`沙漠、废墟与跨国爱情，值得细读`},{year:`2000`,title:`《阿尼尔的幽灵》`,type:`长篇小说`,note:`斯里兰卡内战的调查者`},{year:`2007`,title:`《迪维萨德罗》`,type:`长篇小说`,note:`加州与法国乡间的断裂`},{year:`2011`,title:`《猫桌》`,type:`长篇小说`,note:`海上航程中的少年记忆`},{year:`2018`,title:`《战争之光》`,type:`长篇小说`,note:`战后伦敦的隐秘情报，值得细读`}],position:`他以诗性拼贴把家族史、殖民记忆与战争创伤缝合成流动叙事，句子精炼而意象密集，是加拿大文学中最具国际视野的移民作家之一。`,nobelYear:null},"a-77de57":{slug:`a-77de57`,birthDeath:`1932.08.17 — 2018.08.11`,nationality:`英国/特立尼达裔`,englishName:`V. S. NAIPAUL`,movement:[`后殖民文学`,`旅行写作`,`社会批判`],bio:[`生于特立尼达查瓜纳斯一个印度移民家庭，祖辈以契约劳工身份来此。靠奖学金赴牛津大学攻读英语，毕业后在伦敦为 BBC 制作加勒比节目，并开始小说创作。`,`《米格尔街》以短篇连缀写殖民地童年，《毕司沃斯先生的房子》把父亲式的失败者写成史诗，《模仿者》处理殖民精英的身份空洞，《在自由的国度》获布克奖。`,`《河湾》以非洲内陆的动荡写后殖民国家的崩溃，此后旅行写作《在信徒中间》《印度：受伤的文明》引发激烈争论；《抵达之谜》转向英国乡间的自我流放，二〇〇一年获诺贝尔文学奖。`],controversies:[{tag:`私生活争议`,content:`传记与访谈披露他长期嫖妓、对情妇玛格丽特·古丁施暴，并冷待病中的妻子帕特，私生活因此受到广泛批评。`},{tag:`殖民立场争议`,content:`他对第三世界、伊斯兰与非洲的尖锐贬斥被批评为殖民主义代言，相关言论在其获诺奖后仍持续引发后殖民学者的反驳。`}],works:[{year:`1959`,title:`《米格尔街》`,type:`短篇小说集`,note:`殖民地童年的连缀短篇`},{year:`1961`,title:`《毕司沃斯先生的房子》`,type:`长篇小说`,note:`失败者一生的殖民史诗`},{year:`1967`,title:`《模仿者》`,type:`长篇小说`,note:`殖民精英的身份空洞，可见其创作脉络`},{year:`1971`,title:`《在自由的国度》`,type:`中短篇小说集`,note:`布克奖作品中的流亡者`},{year:`1975`,title:`《游击队员》`,type:`长篇小说`,note:`加勒比革命者的暴力，风格印记鲜明`},{year:`1979`,title:`《河湾》`,type:`长篇小说`,note:`后殖民非洲的崩溃寓言`},{year:`1981`,title:`《在信徒中间》`,type:`旅行写作`,note:`伊斯兰世界的争议观察`},{year:`1987`,title:`《抵达之谜》`,type:`长篇小说`,note:`英国乡间的自我流放，值得细读`},{year:`2001`,title:`《半生》`,type:`长篇小说`,note:`移民与历史夹缝中的一生`}],position:`他以冷静而尖刻的笔触写殖民遗产、移民身份与后殖民国家的失败，把小说与旅行写作合成一种道德诊断，是二战后英语世界最具争议的作家之一。`,positionSource:`— 诺贝尔文学奖授奖辞`,nobelYear:2001},"a-9500ed":{slug:`a-9500ed`,birthDeath:`1930.01.23 — 2017.03.17`,nationality:`圣卢西亚`,englishName:`DEREK WALCOTT`,movement:[`加勒比文学`,`后殖民诗歌`,`史诗写作`],bio:[`生于圣卢西亚卡斯特里，父亲是英国裔水彩画家，母亲是教师与业余演员。幼年丧父，由母亲抚养长大，早年习画并自费出版诗集，后赴牙买加与特立尼达求学。`,`《绿色之夜》确立其加勒比英语诗歌的独特声音，《另一种生活》以自传性长诗写画家与岛屿，《猴山梦》等剧作把克里奥尔语与地方民间仪式搬上现代舞台。`,`《奥梅罗斯》以荷马史诗的格律重写加勒比渔夫与殖民史，获诺贝尔文学奖；晚年《馈赠》《白鹭》继续处理衰老、语言与故乡，同时长期在波士顿大学教授诗歌与戏剧。`],controversies:[],works:[{year:`1948`,title:`《二十五首诗》`,type:`诗集`,note:`自费出版的少年诗作，可见其创作脉络`},{year:`1962`,title:`《绿色之夜》`,type:`诗集`,note:`加勒比英语诗歌的成名作`},{year:`1967`,title:`《猴山梦》`,type:`戏剧`,note:`克里奥尔语与民间仪式`},{year:`1973`,title:`《另一种生活》`,type:`长诗`,note:`画家与岛屿的自传性长诗`},{year:`1979`,title:`《星苹果王国》`,type:`诗集`,note:`殖民历史与海洋意象，风格印记鲜明`},{year:`1990`,title:`《奥梅罗斯》`,type:`长诗`,note:`荷马史诗的加勒比重写`},{year:`1997`,title:`《馈赠》`,type:`诗集`,note:`自然、死亡与加勒比记忆`},{year:`2000`,title:`《提埃波罗的猎犬》`,type:`长诗`,note:`绘画与流亡的互文，值得细读`},{year:`2010`,title:`《白鹭》`,type:`诗集`,note:`晚年的哀歌与岛屿光影`}],position:`他把荷马史诗的规模与加勒比的口语、绘画和殖民创伤结合，证明后殖民英语诗歌可以同时是地方性的与古典的，是二十世纪加勒比文学的最高代表。`,positionSource:`— 诺贝尔文学奖授奖辞`,nobelYear:1992},"a-768977":{slug:`a-768977`,birthDeath:`1912.05.28 — 1990.09.30`,nationality:`澳大利亚`,englishName:`PATRICK WHITE`,movement:[`澳大利亚文学`,`现代主义`,`心理小说`],bio:[`生于伦敦的澳大利亚家庭，半岁随父母回悉尼，在农场与寄宿学校间长大。剑桥大学攻读现代语言，二战期间在英国皇家空军情报部门服役，辗转中东与希腊。`,`《姨妈的故事》以女性流浪者写精神异乡，《人树》把拓荒者家庭写成澳大利亚的创世记，《沃斯》以探险家的失败远征象征殖民者对大陆的征服欲，《乘战车》则引入宗教异象。`,`《活体解剖者》写画家对经验的吞噬，《风暴之眼》以老年女族长处理记忆与权力；一九七三年获诺贝尔文学奖，晚年《叶缘》《特赖本事件》继续触碰性别与阶层禁忌，一九九〇年病逝于悉尼。`],controversies:[],works:[{year:`1939`,title:`《幸福谷》`,type:`长篇小说`,note:`早期澳大利亚乡村小说`},{year:`1948`,title:`《姨妈的故事》`,type:`长篇小说`,note:`女性流浪者的精神异乡`},{year:`1955`,title:`《人树》`,type:`长篇小说`,note:`拓荒者家族的创世记，可见其创作脉络`},{year:`1957`,title:`《沃斯》`,type:`长篇小说`,note:`失败远征与殖民欲望，风格印记鲜明`},{year:`1961`,title:`《乘战车》`,type:`长篇小说`,note:`宗教异象与边缘者群像`},{year:`1966`,title:`《坚实的曼陀罗》`,type:`长篇小说`,note:`双胞胎兄弟的疯狂与艺术`},{year:`1970`,title:`《活体解剖者》`,type:`长篇小说`,note:`画家对经验的吞噬，值得细读`},{year:`1973`,title:`《风暴之眼》`,type:`长篇小说`,note:`老年女族长的记忆与权力`},{year:`1976`,title:`《叶缘》`,type:`长篇小说`,note:`殖民地女性的幸存与越界`},{year:`1979`,title:`《特赖本事件》`,type:`长篇小说`,note:`性别流动与家族秘密，可见其创作脉络`}],position:`他把澳大利亚的殖民经验、土地神话与宗教追问写成高度象征化的现代主义长篇，语言繁复而视野恢宏，是澳大利亚唯一获诺贝尔文学奖的小说家。`,positionSource:`— 诺贝尔文学奖授奖辞`,nobelYear:1973},"a-df1539":{slug:`a-df1539`,birthDeath:`1919.01.01 — 2010.01.27`,nationality:`美国`,englishName:`J. D. SALINGER`,movement:[`战后美国小说`,`成长小说`,`隐逸写作`],bio:[`生于纽约曼哈顿，父亲是犹太裔奶酪进口商，母亲有爱尔兰血统。就读宾夕法尼亚的福吉谷军校，后短暂在纽约大学与哥伦比亚大学旁听写作课，二战期间随步兵师参加诺曼底登陆。`,`《麦田里的守望者》以少年霍尔顿的俚语独白写青春期的厌恶与脆弱，一九五一年出版后成为战后美国青年的文化符号；《九故事》则把禅宗与战后创伤压缩进短篇。`,`此后《弗兰妮与祖伊》《抬高房梁，木匠们》围绕格拉斯家族展开宗教与天才的辩论；一九六五年发表中篇《哈普沃斯十六号》后基本封笔，隐居新罕布什尔乡间，二〇一〇年去世。`],controversies:[{tag:`隐私与版权争议`,content:`他晚年深居简出，多次提起诉讼阻止未经授权的传记、续作与书信出版，围绕作家隐私与作品版权形成长期法律纠纷。`}],works:[{year:`1951`,title:`《麦田里的守望者》`,type:`长篇小说`,note:`少年独白与战后青春，风格印记鲜明`},{year:`1953`,title:`《九故事》`,type:`短篇小说集`,note:`禅宗与战争创伤的短篇`},{year:`1961`,title:`《弗兰妮与祖伊》`,type:`中篇小说`,note:`格拉斯家族的信仰辩论`},{year:`1963`,title:`《抬高房梁，木匠们》`,type:`中篇小说`,note:`格拉斯家族婚礼前夜，值得细读`},{year:`1965`,title:`《哈普沃斯十六号》`,type:`中篇小说`,note:`封笔前的最后发表作品`}],position:`他用一个少年的俚语独白捕捉战后美国的虚伪与孤独，又把格拉斯家族写成宗教与天才的寓言，作品不多却深刻塑造了美国成长小说的语气。`,nobelYear:null},"a-243c69":{slug:`a-243c69`,birthDeath:`1912.05.27 — 1982.06.18`,nationality:`美国`,englishName:`JOHN CHEEVER`,movement:[`美国郊区小说`,`心理现实主义`,`短篇小说`],bio:[`生于马萨诸塞州昆西，父亲是鞋业商人，家境在萧条中败落。因吸烟被塞耶学院开除，后迁居纽约，靠给《纽约客》写短篇与小说维持生活，长期在郊区与城市间迁徙。`,`《巨大的收音机》等短篇以幻想设定写中产焦虑，《瓦普肖特纪事》《瓦普肖特丑闻》把新英格兰家族的衰败写成喜剧，《子弹公园》则转向郊区生活的精神荒芜。`,`《猎鹰者》以监狱为封闭空间写罪与救赎，晚年作品更趋阴郁；他去世后出版的日记揭示长期酗酒、双性恋与家庭痛苦，使读者重新理解其小说中的体面与裂缝。`],controversies:[],works:[{year:`1953`,title:`《巨大的收音机》`,type:`短篇小说集`,note:`中产焦虑的幻想短篇，可见其创作脉络`},{year:`1957`,title:`《瓦普肖特纪事》`,type:`长篇小说`,note:`新英格兰家族的衰败喜剧`},{year:`1958`,title:`《夏迪山的闯宅者》`,type:`短篇小说集`,note:`郊区体面下的道德裂缝`},{year:`1964`,title:`《瓦普肖特丑闻》`,type:`长篇小说`,note:`家族衰败的续篇，风格印记鲜明`},{year:`1969`,title:`《子弹公园》`,type:`长篇小说`,note:`郊区生活的精神荒芜，值得细读`},{year:`1977`,title:`《猎鹰者》`,type:`长篇小说`,note:`监狱中的罪与救赎，可见其创作脉络`},{year:`1978`,title:`《短篇小说集》`,type:`短篇小说集`,note:`纽约客风格的精选，风格印记鲜明`},{year:`1982`,title:`《噢，多么像天堂》`,type:`长篇小说`,note:`晚期对欲望与衰老的回望`}],position:`他以《纽约客》式的精确笔法写美国郊区的体面与溃败，把酗酒、通奸与孤独藏在优雅句子里，是战后美国短篇小说传统的重要承继者。`,nobelYear:null},"a-cab97b":{slug:`a-cab97b`,birthDeath:`1923.05.01 — 1999.12.12`,nationality:`美国`,englishName:`JOSEPH HELLER`,movement:[`黑色幽默`,`战争小说`,`讽刺文学`],bio:[`生于布鲁克林科尼岛，父亲早逝，家境贫寒。二战期间在陆军航空队任轰炸机投弹员，执行六十次任务，这段经历成为其日后战争书写的直接来源。战后在广告业任职多年。`,`《第二十二条军规》以循环逻辑、时间错位与荒诞对话写轰炸机基地的官僚机器，一九六一年出版后成为反战与反体制的代号，也奠定美国黑色幽默小说的基调。`,`《出事了》转向职场与家庭的精神崩溃，《像黄金一样好》讽刺政治野心，《上帝知道》重写大卫王；晚年《关门时间》让旧人物重返纽约，回忆录《无笑之事》记录罕见病与婚姻。`],controversies:[],works:[{year:`1961`,title:`《第二十二条军规》`,type:`长篇小说`,note:`官僚机器的荒诞战争寓言`},{year:`1974`,title:`《出事了》`,type:`长篇小说`,note:`职场与家庭的精神崩溃`},{year:`1979`,title:`《像黄金一样好》`,type:`长篇小说`,note:`政治野心与犹太家庭，值得细读`},{year:`1984`,title:`《上帝知道》`,type:`长篇小说`,note:`大卫王的自嘲式重写，可见其创作脉络`},{year:`1986`,title:`《无笑之事》`,type:`回忆录`,note:`罕见病与婚姻的黑色记录`},{year:`1988`,title:`《想想看》`,type:`长篇小说`,note:`历史与艺术的讽刺拼贴`},{year:`1994`,title:`《关门时间》`,type:`长篇小说`,note:`旧人物重返纽约的续篇`},{year:`2000`,title:`《老艺术家画像》`,type:`长篇小说`,note:`遗作中的写作与死亡，风格印记鲜明`}],position:`他把军事官僚制写成一套自我循环的荒诞逻辑，用笑声处理恐惧与权力，第二十二条军规已成为英语中描述两难困境的通用词。`,nobelYear:null},"a-4713a1":{slug:`a-4713a1`,birthDeath:`1922.11.11 — 2007.04.11`,nationality:`美国`,englishName:`KURT VONNEGUT`,movement:[`黑色幽默`,`科幻讽刺`,`后现代主义`],bio:[`生于印第安纳波利斯一个建筑师家庭，康奈尔大学先修化学后转读新闻。二战中随步兵师在欧洲被俘，关押于德累斯顿，亲历盟军轰炸后的火海，这段经验成为其核心创伤。`,`《自动钢琴》以工业自动化写人的多余，《泰坦星的海妖》《猫的摇篮》用科幻框架讨论自由意志与末日；《五号屠宰场》以时间跳跃与黑色笑话重写德累斯顿，使其成为反战经典。`,`《冠军的早餐》以插图与自嘲作者形象拆解小说形式，晚期《加拉帕戈斯》《蓝胡子》《时震》继续混合回忆、科幻与素描；他晚年成为美国公共生活中最受欢迎的反讽长者。`],controversies:[{tag:`焚书事件`,content:`一九七三年北达科他州德雷克一所学校将《五号屠宰场》列为禁书并投入火炉焚毁，他致信校方，事件成为美国禁书争议的标志性案例。`}],works:[{year:`1952`,title:`《自动钢琴》`,type:`长篇小说`,note:`工业自动化与人的多余`},{year:`1959`,title:`《泰坦星的海妖》`,type:`长篇小说`,note:`科幻框架中的自由意志`},{year:`1961`,title:`《黑夜母亲》`,type:`长篇小说`,note:`战时身份与道德伪善，值得细读`},{year:`1963`,title:`《猫的摇篮》`,type:`长篇小说`,note:`末日科技与黑色幽默，可见其创作脉络`},{year:`1969`,title:`《五号屠宰场》`,type:`长篇小说`,note:`德累斯顿轰炸的时间跳跃`},{year:`1973`,title:`《冠军的早餐》`,type:`长篇小说`,note:`插图与作者自嘲的实验`},{year:`1976`,title:`《滑稽剧》`,type:`长篇小说`,note:`美国历史的荒诞重述，风格印记鲜明`},{year:`1985`,title:`《加拉帕戈斯》`,type:`长篇小说`,note:`进化论与人类末日的寓言`},{year:`1987`,title:`《蓝胡子》`,type:`长篇小说`,note:`画家回忆与艺术欺骗，值得细读`},{year:`1997`,title:`《时震》`,type:`长篇小说`,note:`时间倒流与晚年自白，可见其创作脉络`}],position:`他把科幻、黑色幽默与亲历的战争创伤熔成一种平易而悲悯的美国声音，既讽刺美国技术文明，也坚持对人的愚蠢保持同情。`,nobelYear:null},"a-4e9d89":{slug:`a-4e9d89`,birthDeath:`1937.03.08 —`,nationality:`美国`,englishName:`THOMAS PYNCHON`,movement:[`后现代主义`,`百科全书式小说`,`熵叙事`],bio:[`生于纽约长岛格伦科夫，海军服役后就读康奈尔大学，先修工程物理后转英语。曾在波音公司撰写技术文档，这段经历使他对火箭、密码与官僚系统有持久兴趣。`,`《V.》以多线追寻一个神秘女性，《拍卖第四十九批》把加州消费社会写成符号迷宫；《万有引力之虹》以二战末期的火箭轨迹串联情报、性爱与偏执，获美国国家图书奖。`,`《梅森与迪克逊》重写殖民地测绘，《反抗日》铺展十九世纪末的无政府主义与科技想象；他极少公开露面，拒绝照片与访谈，作品却持续影响美国后现代小说对系统与阴谋的想象。`],controversies:[],works:[{year:`1963`,title:`《V.》`,type:`长篇小说`,note:`多线追寻神秘女性的迷宫`},{year:`1966`,title:`《拍卖第四十九批》`,type:`长篇小说`,note:`消费社会的符号与阴谋`},{year:`1973`,title:`《万有引力之虹》`,type:`长篇小说`,note:`火箭轨迹与二战偏执，风格印记鲜明`},{year:`1984`,title:`《缓慢的学习者》`,type:`短篇小说集`,note:`早期短篇与自序，值得细读`},{year:`1990`,title:`《葡萄园》`,type:`长篇小说`,note:`媒体政治与加州反文化`},{year:`1997`,title:`《梅森与迪克逊》`,type:`长篇小说`,note:`殖民地测绘的史诗重写`},{year:`2006`,title:`《反抗日》`,type:`长篇小说`,note:`无政府主义与科技想象`},{year:`2009`,title:`《性本恶》`,type:`长篇小说`,note:`洛杉矶侦探与消费文化`},{year:`2013`,title:`《边缘》`,type:`长篇小说`,note:`网络时代的偏执与记忆`}],position:`他以百科全书式的知识、阴谋叙事与熵的隐喻描绘技术官僚社会，把通俗类型提升为复杂的系统小说，是战后美国后现代文学最难绕开的坐标。`,nobelYear:null},"a-f3af3b":{slug:`a-f3af3b`,birthDeath:`1936.11.20 —`,nationality:`美国`,englishName:`DON DELILLO`,movement:[`后现代主义`,`媒介社会小说`,`系统小说`],bio:[`生于纽约布朗克斯的意大利移民家庭，福特汉姆大学攻读传播学，毕业后在广告公司工作五年。广告语言、电视影像与城市噪音，后来成为其小说反复处理的材料。`,`《美国》以广告人的西部之旅写影像消费，《白噪音》把超市、电视与有毒气体事件写成中产家庭寓言，《天秤座》则以肯尼迪遇刺案重构阴谋与美国历史叙述。`,`《毛二世》讨论作家与恐怖主义，《地下世界》以棒球与核废料编织冷战全景；九一一后《坠落的人》转向创伤与图像，晚期《零K》处理冷冻技术与死亡，他始终关注媒介如何塑造集体恐惧。`],controversies:[],works:[{year:`1971`,title:`《美国》`,type:`长篇小说`,note:`广告人的西部与影像消费`},{year:`1972`,title:`《终点区》`,type:`长篇小说`,note:`橄榄球与战争语言，可见其创作脉络`},{year:`1973`,title:`《大琼斯街》`,type:`长篇小说`,note:`摇滚明星与城市地下，风格印记鲜明`},{year:`1976`,title:`《拉特纳之星》`,type:`长篇小说`,note:`科学、数学与疯狂，值得细读`},{year:`1982`,title:`《名字》`,type:`长篇小说`,note:`跨国邪教与语言权力，可见其创作脉络`},{year:`1985`,title:`《白噪音》`,type:`长篇小说`,note:`消费社会与死亡恐惧，风格印记鲜明`},{year:`1988`,title:`《天秤座》`,type:`长篇小说`,note:`肯尼迪遇刺的阴谋重述`},{year:`1991`,title:`《毛二世》`,type:`长篇小说`,note:`作家、崇拜与恐怖主义，可见其创作脉络`},{year:`1997`,title:`《地下世界》`,type:`长篇小说`,note:`冷战全景与核废料，值得细读`},{year:`2007`,title:`《坠落的人》`,type:`长篇小说`,note:`九一一后的创伤与图像`}],position:`他把广告、电视与阴谋论的语言写进小说，揭示美国媒介社会如何制造恐惧与欲望，是当代美国最敏锐的系统观察者之一。`,nobelYear:null},"a-d9a86b":{slug:`a-d9a86b`,birthDeath:`1933.03.19 — 2018.05.22`,nationality:`美国`,englishName:`PHILIP ROTH`,movement:[`美国犹太小说`,`自传性虚构`,`元小说`],bio:[`生于新泽西州纽瓦克一个犹太移民家庭，在韦夸希克区长大。巴克内尔大学本科毕业后赴芝加哥大学攻读文学，早年以短篇与《再见，哥伦布》进入文坛。`,`《波特诺伊的怨诉》以独白式自嘲写犹太家庭与性压抑，引发巨大争议并成为畅销书；此后他以作家祖克曼为替身，连续写作《鬼作家》《被束缚的祖克曼》等，拆解虚构与自传的边界。`,`九十年代《美国牧歌》《我嫁给了共产党人》《人性污点》以战后美国为背景审视背叛与身份政治；《反美阴谋》把历史假设写成家族记忆，二〇一〇年《复仇女神》后宣布封笔。`],controversies:[{tag:`性别再现争议`,content:`《波特诺伊的怨诉》出版后被部分女性主义批评者指为厌女，罗斯在后续作品中反复回应这一指控，论战持续数十年。`}],works:[{year:`1959`,title:`《再见，哥伦布》`,type:`中短篇小说集`,note:`犹太青年与阶层焦虑，可见其创作脉络`},{year:`1969`,title:`《波特诺伊的怨诉》`,type:`长篇小说`,note:`性压抑与犹太家庭的独白`},{year:`1979`,title:`《鬼作家》`,type:`长篇小说`,note:`祖克曼系列的开篇，风格印记鲜明`},{year:`1986`,title:`《被束缚的祖克曼》`,type:`长篇小说`,note:`虚构与自传的边界，值得细读`},{year:`1993`,title:`《夏洛克战役》`,type:`长篇小说`,note:`身份冒充与犹太复国政治`},{year:`1997`,title:`《美国牧歌》`,type:`长篇小说`,note:`战后美国梦的破裂，可见其创作脉络`},{year:`1998`,title:`《我嫁给了共产党人》`,type:`长篇小说`,note:`麦卡锡时代的背叛记忆`},{year:`2000`,title:`《人性污点》`,type:`长篇小说`,note:`种族伪装与学术政治，风格印记鲜明`},{year:`2004`,title:`《反美阴谋》`,type:`长篇小说`,note:`林德伯格当选的历史假设`},{year:`2010`,title:`《复仇女神》`,type:`长篇小说`,note:`小儿麻痹症与代际责任`}],position:`他把犹太家庭、性焦虑与美国政治写进不断自我拆解的叙事，让祖克曼成为二十世纪后半叶美国作家意识的化身，也是最有争议的文学自传者之一。`,nobelYear:null},"a-f68db5":{slug:`a-f68db5`,birthDeath:`1933.07.20 — 2023.06.13`,nationality:`美国`,englishName:`CORMAC MCCARTHY`,movement:[`南方哥特`,`西部小说`,`后启示录小说`],bio:[`生于罗德岛普罗维登斯，幼年随家人迁往田纳西诺克斯维尔，在阿巴拉契亚山区长大。未完成大学学业，早年写短篇并大量阅读，长期生活极为清贫。`,`《果园守夜人》《外围黑暗》《上帝之子》以南方哥特的暴力与孤立写底层边缘人，《萨特里》则以田纳西河上的流浪汉写城市边缘的尊严，语言浓密而极为古拙。`,`《血色子午线》以美墨边境的屠杀写人性之恶，《所有漂亮的马》开启边境三部曲；《老无所依》《路》把暴力与父职推向当代，后者获普利策奖，晚期《乘客》《斯特拉·马里斯》转向科学与死亡。`],controversies:[],works:[{year:`1965`,title:`《果园守夜人》`,type:`长篇小说`,note:`南方山区的暴力与孤立`},{year:`1968`,title:`《外围黑暗》`,type:`长篇小说`,note:`哥特式的乱伦与追杀，值得细读`},{year:`1973`,title:`《上帝之子》`,type:`长篇小说`,note:`边缘人的暴力与荒野，可见其创作脉络`},{year:`1979`,title:`《萨特里》`,type:`长篇小说`,note:`田纳西河上的流浪汉史诗`},{year:`1985`,title:`《血色子午线》`,type:`长篇小说`,note:`美墨边境的屠杀寓言，风格印记鲜明`},{year:`1992`,title:`《所有漂亮的马》`,type:`长篇小说`,note:`边境三部曲的开篇，值得细读`},{year:`1994`,title:`《穿越》`,type:`长篇小说`,note:`少年与狼的边境旅程，可见其创作脉络`},{year:`2005`,title:`《老无所依》`,type:`长篇小说`,note:`毒品暴力与命运偶然，风格印记鲜明`},{year:`2006`,title:`《路》`,type:`长篇小说`,note:`后启示录中的父子之行`},{year:`2022`,title:`《乘客》`,type:`长篇小说`,note:`科学、死亡与深海记忆，风格印记鲜明`}],position:`他用古拙而密集的散文写边境、暴力与末日，把美国西部神话拆成关于人性之恶与父职的寓言，是当代美国小说中最具神话规模的作家之一。`,nobelYear:null},"a-2ff105":{slug:`a-2ff105`,birthDeath:`1938.05.25 — 1988.08.02`,nationality:`美国`,englishName:`RAYMOND CARVER`,movement:[`极简主义`,`美国短篇小说`,`新现实主义`],bio:[`生于俄勒冈州克拉茨卡尼，父亲是锯木工，家庭在华盛顿州与加州间迁徙。十九岁结婚并育有子女，靠打零工与写作课程维持生活，长期与酗酒搏斗，一九七七年戒酒。`,`《请你安静些，好吗？》获美国国家图书奖提名，《当我们谈论爱情时我们在谈论什么》以削减到极致的对话与留白确立极简主义风格，《大教堂》则转向更温暖、更开放的结尾。`,`他的小说多写失业、酗酒、婚姻破裂与微小善意，语言干净而节奏克制；晚期诗作与《我打电话的地方》总结其短篇成就，一九八八年因肺癌去世，年仅五十岁。`],controversies:[{tag:`编辑删改争议`,content:`编辑戈登·利什对其早期小说大幅删改，原稿后以《初学者》出版，围绕作者意图与编辑权力何者塑造了极简主义经典的争论持续至今。`}],works:[{year:`1976`,title:`《请你安静些，好吗？》`,type:`短篇小说集`,note:`失业与婚姻的早期短篇`},{year:`1977`,title:`《愤怒的季节》`,type:`诗集`,note:`早期诗作中的底层生活`},{year:`1981`,title:`《当我们谈论爱情时我们在谈论什么》`,type:`短篇小说集`,note:`极简主义的标志性短篇`},{year:`1983`,title:`《大教堂》`,type:`短篇小说集`,note:`更温暖开放的晚期风格`},{year:`1985`,title:`《水流与水道》`,type:`诗集`,note:`自然意象与日常观察，值得细读`},{year:`1988`,title:`《我打电话的地方》`,type:`短篇小说集`,note:`短篇生涯的自我精选，可见其创作脉络`},{year:`1989`,title:`《通往瀑布的新路》`,type:`诗集`,note:`临终前的爱情与告别，风格印记鲜明`}],position:`他把美国蓝领生活的失意与温情压缩进极简对话，用省略和沉默恢复短篇小说的力量，是二十世纪后半叶最有影响力的英语短篇作家之一。`,nobelYear:null},"a-8bcf8d":{slug:`a-8bcf8d`,birthDeath:`1929.10.21 — 2018.01.22`,nationality:`美国`,englishName:`URSULA K. LE GUIN`,movement:[`科幻小说`,`奇幻文学`,`人类学想象`],bio:[`生于加州伯克利，父亲是人类学家阿尔弗雷德·克罗伯，母亲是作家西奥多拉·克罗伯。家庭中的人类学讨论与印第安文化材料，深刻影响她对异文明与性别制度的想象。`,`《地海传说》以真名与平衡构建奇幻体系，《黑暗的左手》把性别流动写成外星社会实验，《一无所有》以无政府主义与资本主义双星球对照，探讨政治想象的边界。`,`《永远回家》混合小说、诗歌与人类学档案，《拉维尼亚》重写《埃涅阿斯纪》中的沉默女性；她晚年以随笔与演讲批评资本与性别权力，二〇一八年去世，影响横跨通俗与严肃文学。`],controversies:[],works:[{year:`1966`,title:`《罗坎农的世界》`,type:`长篇小说`,note:`海尼什系列的首部，值得细读`},{year:`1968`,title:`《地海传说》`,type:`长篇小说`,note:`真名与平衡的奇幻经典`},{year:`1969`,title:`《黑暗的左手》`,type:`长篇小说`,note:`性别流动的外星社会实验`},{year:`1971`,title:`《天钧》`,type:`长篇小说`,note:`梦境改写现实的寓言，可见其创作脉络`},{year:`1974`,title:`《一无所有》`,type:`长篇小说`,note:`无政府与资本主义双星球`},{year:`1976`,title:`《世界词语是森林》`,type:`长篇小说`,note:`殖民、生态与战争，风格印记鲜明`},{year:`1985`,title:`《永远回家》`,type:`跨文体作品`,note:`小说、诗歌与人类学档案`},{year:`2000`,title:`《讲述》`,type:`长篇小说`,note:`口头传统与真理制度，值得细读`},{year:`2008`,title:`《拉维尼亚》`,type:`长篇小说`,note:`史诗沉默女性的重写，可见其创作脉络`}],position:`她以人类学式的想象构造异文明，把性别、政治与生态问题写进科幻和奇幻，提升了两种类型的智性尊严，是二十世纪最具影响力的思辨小说家之一。`,nobelYear:null},"a-230e26":{slug:`a-230e26`,birthDeath:`1944.02.09 —`,nationality:`美国`,englishName:`ALICE WALKER`,movement:[`非裔美国文学`,`女性主义`,`书信体小说`],bio:[`生于佐治亚州伊顿顿的佃农家庭，是八个孩子中最小的一个。八岁时被玩具枪伤及右眼，视力受损使她转向阅读与观察；后在斯佩尔曼学院与莎拉·劳伦斯学院求学，参与民权运动。`,`《格兰奇·科普兰的第三次生命》写南方黑人家庭的代际暴力，《梅里迪安》以民权运动中的女性写牺牲与背叛；《紫色》以书信体让黑人女性彼此命名，获普利策奖并被改编为电影。`,`她提出妇女主义一词，以区别于白人女性主义，《寻找我们母亲的花园》重新发掘赫斯顿等被遗忘的传统；后期《我熟悉的神殿》《拥有快乐的秘密》延伸至非洲与女性割礼议题，争议与影响并存。`],controversies:[{tag:`黑人男性再现争议`,content:`《紫色》因把黑人男性多写成施暴者而受到部分黑人评论者批评，认为其迎合了外部刻板印象，沃克则坚持这是对幸存者经验的诚实书写。`}],works:[{year:`1968`,title:`《一度》`,type:`诗集`,note:`民权运动中的早期诗作`},{year:`1970`,title:`《格兰奇·科普兰的第三次生命》`,type:`长篇小说`,note:`南方黑人家庭的代际暴力`},{year:`1976`,title:`《梅里迪安》`,type:`长篇小说`,note:`民权运动中的女性牺牲`},{year:`1982`,title:`《紫色》`,type:`长篇小说`,note:`书信体中的黑人女性情谊`},{year:`1983`,title:`《寻找我们母亲的花园》`,type:`随笔集`,note:`妇女主义与黑人女性传统`},{year:`1989`,title:`《我熟悉的神殿》`,type:`长篇小说`,note:`跨代女性与精神传承，风格印记鲜明`},{year:`1992`,title:`《拥有快乐的秘密》`,type:`长篇小说`,note:`女性割礼与殖民记忆，值得细读`},{year:`1998`,title:`《我父亲微笑的光芒》`,type:`长篇小说`,note:`父女关系与性压抑，可见其创作脉络`},{year:`2004`,title:`《现在正是敞开心扉的时候》`,type:`长篇小说`,note:`亚马逊与精神旅程，风格印记鲜明`}],position:`她把黑人女性的身体、语言与精神传统写进书信、小说与随笔，提出妇女主义以区别于白人女性主义，是当代美国最具政治行动性的作家之一。`,nobelYear:null},"a-5f2f5d":{slug:`a-5f2f5d`,birthDeath:`1969.11.06 —`,nationality:`美国`,englishName:`COLSON WHITEHEAD`,movement:[`历史小说`,`非裔美国文学`,`后现代主义`],bio:[`生于纽约曼哈顿，在曼哈顿上西区与哈莱姆一带长大。哈佛学院毕业后做过撰稿人与编辑，早期小说以类型混写与概念设定受到评论界广泛关注。`,`《直觉主义者》以电梯检查员写种族与城市权力，《约翰·亨利日》围绕民间英雄纪念碑展开，《萨格港》转向黑人中产家庭的夏日记忆，《第一区》则以丧尸末日写纽约的阶层结构。`,`《地下铁道》以逃亡铁路的实体化写美国奴隶制，《镍孩儿》以佛罗里达少年管教学校的真实历史获普利策奖；近作《哈莱姆洗牌》《骗子宣言》转向二十世纪纽约的犯罪与社群，历史批判始终包裹在类型叙事中。`],controversies:[],works:[{year:`1999`,title:`《直觉主义者》`,type:`长篇小说`,note:`电梯检查员与城市种族权力`},{year:`2001`,title:`《约翰·亨利日》`,type:`长篇小说`,note:`民间英雄与纪念碑政治`},{year:`2006`,title:`《顶点隐藏伤害》`,type:`长篇小说`,note:`命名、广告与身份，值得细读`},{year:`2009`,title:`《萨格港》`,type:`长篇小说`,note:`黑人中产家庭的夏日记忆`},{year:`2011`,title:`《第一区》`,type:`长篇小说`,note:`丧尸末日与阶层结构，可见其创作脉络`},{year:`2016`,title:`《地下铁道》`,type:`长篇小说`,note:`实体化逃亡铁路的奴隶制`},{year:`2019`,title:`《镍孩儿》`,type:`长篇小说`,note:`少年管教学校的真实历史`},{year:`2021`,title:`《哈莱姆洗牌》`,type:`长篇小说`,note:`二十世纪纽约的犯罪与社群`},{year:`2023`,title:`《骗子宣言》`,type:`长篇小说`,note:`哈莱姆犯罪史诗的续篇`}],position:`他借类型小说的外壳处理奴隶制、种族隔离与城市权力，把历史创伤写成可读的冒险叙事，是二十一世纪美国最受瞩目的历史小说家之一。`,nobelYear:null},"a-7b52ea":{slug:`a-7b52ea`,birthDeath:`1960.08.08 —`,nationality:`美国`,englishName:`JEFFREY EUGENIDES`,movement:[`美国移民小说`,`成长小说`,`黑色喜剧`],bio:[`生于底特律一个希腊裔美国中产家庭，在密歇根郊区长大。布朗大学攻读英语，后在斯坦福大学获写作硕士，早年以短篇与文学杂志编辑工作积累经验。`,`《处女自杀》以邻居少年的集体回忆写五姐妹的封闭与死亡，《中性》以双性人主人公的家族史横跨希腊移民与底特律暴乱，获普利策奖，确立其黑色幽默与史诗视野。`,`《婚姻情节》转向大学校园与书信体爱情，《新鲜抱怨》收束其短篇创作；近作《独异性》以编辑、小说家与教授的三重身份重写柏林与底特律，继续探讨身份与叙事的关系。`],controversies:[],works:[{year:`1993`,title:`《疑凶档案》`,type:`长篇小说`,note:`又译《处女自杀》，邻居少年回忆`},{year:`2002`,title:`《中性》`,type:`长篇小说`,note:`双性人家族史与普利策奖`},{year:`2011`,title:`《婚姻情节》`,type:`长篇小说`,note:`校园爱情与书信体叙事`},{year:`2017`,title:`《新鲜抱怨》`,type:`短篇小说集`,note:`短篇创作的阶段总结，风格印记鲜明`},{year:`2022`,title:`《独异性》`,type:`长篇小说`,note:`编辑与作家的三重身份`}],position:`他以黑色幽默与家族史诗处理移民同化、性别身份与美国梦的裂缝，既能让概念设定落地为人物命运，也保持对叙事本身的反思。`,nobelYear:null},"a-be9944":{slug:`a-be9944`,birthDeath:`1959.08.17 —`,nationality:`美国`,englishName:`JONATHAN FRANZEN`,movement:[`美国社会小说`,`现实主义`,`家庭小说`],bio:[`生于伊利诺伊州西泉镇，父亲是铁路工程师。斯沃斯莫尔学院毕业后赴德国学习，回美后为《纽约客》等刊物撰稿，早期小说以城市政治与系统权力为题。`,`《第二十七城》以圣路易斯的政治阴谋写后工业城市，《强震》处理环保与地产；《纠正》以中西部家庭三代人的圣诞聚会写消费社会与衰老，获美国国家图书奖。`,`《自由》以婚姻与环保政治写新千年美国，《纯洁》转向东欧与网络泄密；随笔集《如何独处》批评电视与社交媒体，晚年《十字路口》以七十年代教会青年写道德选择。`],controversies:[{tag:`奥普拉读书俱乐部风波`,content:`二〇〇一年《纠正》入选奥普拉读书俱乐部后，他公开表示对商业选书机制不适，引发与奥普拉及读者的公开冲突，成为文学与大众市场关系的著名案例。`}],works:[{year:`1988`,title:`《第二十七城》`,type:`长篇小说`,note:`后工业城市的政治阴谋`},{year:`1992`,title:`《强震》`,type:`长篇小说`,note:`环保、地产与家庭，值得细读`},{year:`2001`,title:`《纠正》`,type:`长篇小说`,note:`中西部家庭的衰老与消费`},{year:`2002`,title:`《如何独处》`,type:`随笔集`,note:`电视、隐私与阅读，可见其创作脉络`},{year:`2010`,title:`《自由》`,type:`长篇小说`,note:`婚姻、环保与新千年美国`},{year:`2015`,title:`《纯洁》`,type:`长篇小说`,note:`东欧、网络与代际秘密，值得细读`},{year:`2018`,title:`《地球尽头的尽头》`,type:`随笔集`,note:`气候、鸟类与晚期写作，可见其创作脉络`},{year:`2021`,title:`《十字路口》`,type:`长篇小说`,note:`七十年代教会青年的道德`}],position:`他以十九世纪式的社会小说规模写美国家庭与制度，把婚姻、环保与媒体纳入道德叙事，是当代美国现实主义最自觉的继承者与争论中心。`,nobelYear:null},"a-284f72":{slug:`a-284f72`,birthDeath:`1949.01.01 — 2017.05.24`,nationality:`美国`,englishName:`DENIS JOHNSON`,movement:[`美国新现实主义`,`诗性小说`,`边缘叙事`],bio:[`生于慕尼黑，父亲在国务院工作，童年在东京、马尼拉与华盛顿之间迁徙。爱荷华大学写作班出身，早年以诗集成名，长期酗酒与吸毒，边缘经验成为其小说核心。`,`《天使》以流浪汉与罪犯的公路旅程写美国底层的暴力，《菲斯克阿多罗》以核战后岛屿写文明记忆；《耶稣之子》用十一则短篇串起瘾君子的幻觉与温情，语言诗性而破碎。`,`《树烟》以越战情报与冷战幻觉获美国国家图书奖，《火车梦》以短篇篇幅写西部劳工的一生，《笑面怪物》转向非洲；二〇一七年去世，留下横跨诗与小说的独特声音。`],controversies:[],works:[{year:`1969`,title:`《海豹中的人》`,type:`诗集`,note:`早期诗作中的边缘经验`},{year:`1983`,title:`《天使》`,type:`长篇小说`,note:`流浪汉与罪犯的公路，风格印记鲜明`},{year:`1985`,title:`《菲斯克阿多罗》`,type:`长篇小说`,note:`核战后岛屿的文明记忆`},{year:`1986`,title:`《正午之星》`,type:`长篇小说`,note:`中美洲战地的记者与欲望`},{year:`1992`,title:`《耶稣之子》`,type:`短篇小说集`,note:`瘾君子的幻觉与温情，值得细读`},{year:`1997`,title:`《已死》`,type:`长篇小说`,note:`侦探、毒品与加州海岸，风格印记鲜明`},{year:`2007`,title:`《树烟》`,type:`长篇小说`,note:`越战情报与冷战幻觉，可见其创作脉络`},{year:`2011`,title:`《火车梦》`,type:`中篇小说`,note:`西部劳工一生的短篇史诗`},{year:`2014`,title:`《笑面怪物》`,type:`长篇小说`,note:`非洲战地的幻觉旅行，风格印记鲜明`}],position:`他把瘾君子、流浪汉与战地记者的边缘经验写成诗性叙事，句子在幻觉与清醒之间摆动，是当代美国小说中最具抒情强度的声音之一。`,nobelYear:null},"a-affe49":{slug:`a-affe49`,birthDeath:`1934.12.05 — 2021.12.23`,nationality:`美国`,englishName:`JOAN DIDION`,movement:[`新新闻主义`,`个人随笔`,`加州书写`],bio:[`生于加州萨克拉门托，家族世代与西部迁徙有关。伯克利加州大学攻读英语，毕业后在《时尚》杂志工作，六十年代以自由撰稿人身份写加州与纽约的报道。`,`《向伯利恒跋涉》以碎片式报道写嬉皮士时代的失序，《按部就班》以冷漠句法写好莱坞女性的崩溃，《白色专辑》把个人记忆与公共事件并置，确立其冷静自剖的文体。`,`《萨尔瓦多》《迈阿密》转向中美洲与古巴流亡社群，《奇想之年》以丈夫猝死后的哀悼拆解叙事理性，《蓝色夜晚》写女儿之死；二〇二一年去世，被视为新新闻主义最重要的文体家。`],controversies:[{tag:`新新闻主义真实性争议`,content:`她以主观感受与场景重构写报道，曾被传统记者质疑事实与文学想象的边界，这场争论构成新新闻主义评价史的一部分。`}],works:[{year:`1963`,title:`《河》`,type:`长篇小说`,note:`加州家族与婚姻的早期小说`},{year:`1968`,title:`《向伯利恒跋涉》`,type:`随笔集`,note:`嬉皮士时代的碎片报道`},{year:`1970`,title:`《按部就班》`,type:`长篇小说`,note:`好莱坞女性的冷漠崩溃`},{year:`1977`,title:`《共同的祈祷书》`,type:`长篇小说`,note:`跨国婚姻与政治动荡，值得细读`},{year:`1979`,title:`《白色专辑》`,type:`随笔集`,note:`个人记忆与公共事件，可见其创作脉络`},{year:`1983`,title:`《萨尔瓦多》`,type:`报道`,note:`内战中的暴力与恐惧，风格印记鲜明`},{year:`1987`,title:`《迈阿密》`,type:`报道`,note:`古巴流亡社群的政治，值得细读`},{year:`2005`,title:`《奇想之年》`,type:`回忆录`,note:`丈夫猝死后的哀悼，可见其创作脉络`},{year:`2011`,title:`《蓝色夜晚》`,type:`回忆录`,note:`女儿之死与养育记忆，风格印记鲜明`}],position:`她用冷静、节奏精准的句子把个人丧失与公共危机并置，既开创了新新闻主义的文体，也把哀悼写成关于叙事本身的反思。`,nobelYear:null},"a-63a419":{slug:`a-63a419`,birthDeath:`1938.06.16 —`,nationality:`美国`,englishName:`JOYCE CAROL OATES`,movement:[`美国心理现实主义`,`哥特小说`,`多产写作`],bio:[`生于纽约州洛克波特，在工人阶级天主教家庭长大。锡拉丘兹大学毕业后赴威斯康星大学攻读文学，一九六三年出版首部短篇集，此后以极高产量横跨长篇、短篇、诗歌与评论。`,`《他们》以底特律贫民家庭写阶层与暴力，获美国国家图书奖，《奇迹之地》以哥特式家族史写美国梦的阴暗怪诞，《贝尔弗勒》则把吸血鬼传说植入美国边疆。`,`《黑水》重写肯尼迪事件，《金发》以梦露为原型写名人身体的消耗，《大瀑布》转向尼亚加拉的家庭崩溃；她以本名与笔名罗莎蒙德·史密斯写作，持续关注性别暴力与美国社会的阴暗面。`],controversies:[],works:[{year:`1964`,title:`《颤抖着坠落》`,type:`长篇小说`,note:`早期哥特风格的家庭，值得细读`},{year:`1969`,title:`《他们》`,type:`长篇小说`,note:`底特律贫民家庭的阶层暴力`},{year:`1971`,title:`《奇迹之地》`,type:`长篇小说`,note:`哥特式家族与美国梦，可见其创作脉络`},{year:`1980`,title:`《贝尔弗勒》`,type:`长篇小说`,note:`吸血鬼传说与美国边疆`},{year:`1992`,title:`《黑水》`,type:`长篇小说`,note:`肯尼迪事件的重写，风格印记鲜明`},{year:`1994`,title:`《我为此而活》`,type:`长篇小说`,note:`政治野心与城市腐败，值得细读`},{year:`2000`,title:`《金发》`,type:`长篇小说`,note:`梦露式名人身体的消耗`},{year:`2004`,title:`《大瀑布》`,type:`长篇小说`,note:`尼亚加拉的家庭崩溃，可见其创作脉络`},{year:`2014`,title:`《迦太基》`,type:`长篇小说`,note:`失踪、战争与小镇秘密，值得细读`}],position:`她以惊人的产量与心理强度写美国暴力、性别与阶层，把哥特传统带进当代社会新闻，是战后美国文学中最持续也最难归类的观察者。`,nobelYear:null},"a-149f24":{slug:`a-149f24`,birthDeath:`1945.06.19 —`,nationality:`美国`,englishName:`TOBIAS WOLFF`,movement:[`美国短篇小说`,`回忆录`,`极简主义`],bio:[`生于阿拉巴马州伯明翰，幼年随母亲与继父在西部各地迁徙，继父的严厉与家庭的漂泊成为其回忆录素材。曾入伍赴越南，后就读牛津大学与斯坦福大学写作班。`,`《北美殉道者花园》以普通人的失败与自负写短篇，《军营窃贼》获福克纳奖；回忆录《这男孩的一生》以少年视角写继父关系与自我塑造，成为美国回忆录写作的典范。`,`《火之夜》继续精炼其克制而带幽默的短篇风格，《老学校》以寄宿学校写文学抱负与阶层；他长期编辑短篇小说选本并在斯坦福任教，对美国短篇传统的传播影响深远。`],controversies:[],works:[{year:`1975`,title:`《丑陋的谣言》`,type:`长篇小说`,note:`早期讽刺与校园生活，风格印记鲜明`},{year:`1981`,title:`《北美殉道者花园》`,type:`短篇小说集`,note:`普通人的失败与自负，值得细读`},{year:`1984`,title:`《军营窃贼》`,type:`中篇小说`,note:`军营中的道德考验，可见其创作脉络`},{year:`1989`,title:`《这男孩的一生》`,type:`回忆录`,note:`继父关系与少年自我塑造`},{year:`1996`,title:`《问题之夜》`,type:`短篇小说集`,note:`克制幽默的晚期短篇，风格印记鲜明`},{year:`2003`,title:`《老学校》`,type:`长篇小说`,note:`寄宿学校的文学抱负，值得细读`},{year:`2008`,title:`《我们的故事开始了》`,type:`短篇小说集`,note:`短篇生涯的精选，可见其创作脉络`}],position:`他以克制、幽默而精确的短篇写普通人的自尊与失败，又以回忆录把少年漂泊写成美国自我塑造的神话，是当代美国短篇小说的重要守门人。`,nobelYear:null},"a-117718":{slug:`a-117718`,birthDeath:`1922.08.18 — 2008.02.18`,nationality:`法国`,englishName:`ALAIN ROBBE-GRILLET`,movement:[`新小说`,`物本主义`,`形式实验`],bio:[`生于布列塔尼布雷斯特，受过农艺与统计学训练，战后在马提尼克与非洲从事农业研究。五十年代初开始写作，并任职于午夜出版社，成为新小说最重要的理论代言人。`,`《橡皮》以侦探小说的骨架反复重写同一场景，《窥视者》以客观镜头般的描写制造罪行疑云，《嫉妒》则用香蕉林、柱影与墙上的蜈蚣替代人物心理，把物写到极致。`,`《为了一种新小说》系统提出拒绝情节、人物与心理现实的主张；他与阿兰·雷乃合作电影《去年在马里昂巴德》，晚年写自传性三部曲，继续把记忆、色情与虚构混为一体。`],controversies:[],works:[{year:`1953`,title:`《橡皮》`,type:`长篇小说`,note:`侦探骨架与场景重复，风格印记鲜明`},{year:`1955`,title:`《窥视者》`,type:`长篇小说`,note:`客观镜头与罪行疑云，值得细读`},{year:`1957`,title:`《嫉妒》`,type:`长篇小说`,note:`物象替代人物心理，可见其创作脉络`},{year:`1959`,title:`《在迷宫里》`,type:`长篇小说`,note:`城市空间与叙事循环，风格印记鲜明`},{year:`1963`,title:`《为了一种新小说》`,type:`文论`,note:`新小说的理论宣言，值得细读`},{year:`1965`,title:`《约会之屋》`,type:`长篇小说`,note:`殖民地、梦境与拼贴，可见其创作脉络`},{year:`1970`,title:`《纽约革命计划》`,type:`长篇小说`,note:`城市、暴力与元叙事，风格印记鲜明`},{year:`1984`,title:`《重现的镜子》`,type:`自传`,note:`记忆与虚构的自我书写`}],position:`他把小说从心理与情节中剥离，强迫读者面对物象、空间与叙事的构造本身，是新小说理论最清晰的提出者，也是法国战后先锋文学的关键组织者。`,nobelYear:null},"a-39b7ad":{slug:`a-39b7ad`,birthDeath:`1900.07.18 — 1999.10.19`,nationality:`法国`,englishName:`NATHALIE SARRAUTE`,movement:[`新小说`,`向性写作`,`心理独白`],bio:[`生于俄国伊万诺沃-沃兹涅先斯克，幼年随家庭在巴黎与圣彼得堡之间往返，后在巴黎攻读法律与文学。俄语与法语的双重经验，使她对语言内部的细微颤动格外敏感。`,`《向性》以极短片段写人与人之间几乎不可察觉的心理倾向，萨特作序的《一个陌生人的画像》则把叙述者变成窥视他人内心的声音，《马尔特罗》继续拆解对话中的权力。`,`《天象馆》以家庭对话写语言的表演性，《金色果实》讽刺文学圈的自我崇拜，《童年》以碎片回忆重构造语言之前的感受；她被视为新小说中最专注于意识微观运动的一位。`],controversies:[],works:[{year:`1939`,title:`《向性》`,type:`短篇集`,note:`心理倾向的极短片段，值得细读`},{year:`1948`,title:`《一个陌生人的画像》`,type:`长篇小说`,note:`萨特作序的内心窥视，可见其创作脉络`},{year:`1953`,title:`《马尔特罗》`,type:`长篇小说`,note:`对话中的权力与猜疑，风格印记鲜明`},{year:`1959`,title:`《天象馆》`,type:`长篇小说`,note:`家庭对话的语言表演，值得细读`},{year:`1963`,title:`《金色果实》`,type:`长篇小说`,note:`文学圈的自我崇拜，可见其创作脉络`},{year:`1968`,title:`《生死之间》`,type:`长篇小说`,note:`写作与死亡的边界，风格印记鲜明`},{year:`1972`,title:`《你听见了吗》`,type:`长篇小说`,note:`声音、误解与家庭，值得细读`},{year:`1983`,title:`《童年》`,type:`自传`,note:`语言之前的碎片记忆，可见其创作脉络`},{year:`1995`,title:`《这里》`,type:`长篇小说`,note:`日常词语的极限探索，风格印记鲜明`}],position:`她把小说缩减为对话与心理的微小振动，拒绝情节与人物肖像，用语言本身制造紧张，是新小说中最彻底也最持久的形式探索者。`,nobelYear:null},"a-27a510":{slug:`a-27a510`,birthDeath:`1926.09.14 — 2016.08.24`,nationality:`法国`,englishName:`MICHEL BUTOR`,movement:[`新小说`,`空间叙事`,`形式实验`],bio:[`生于法国北部蒙斯昂巴勒尔，攻读哲学与文学，后在埃及、曼彻斯特、希腊与美国任教。长期的旅行与教学经验，使他的小说始终带有城市、建筑与地理的精确感。`,`《米兰通道》以公寓楼的空间结构组织多个人物，《时间表》以日记与城市时间写殖民地的道德困境，《变》用第二人称写一趟巴黎到罗马的火车旅程，获勒诺多奖。`,`《度》以寄宿学校的空间与多重视角展开，《移动》把美国旅行写成拼贴式的地理诗，《圣马可的描述》则混合建筑说明与历史；他晚年继续写诗、广播剧与艺术评论，形式实验从未停止。`],controversies:[],works:[{year:`1954`,title:`《米兰通道》`,type:`长篇小说`,note:`公寓楼空间中的多人物`},{year:`1956`,title:`《时间表》`,type:`长篇小说`,note:`日记、城市与殖民地道德`},{year:`1957`,title:`《变》`,type:`长篇小说`,note:`第二人称的火车旅程，值得细读`},{year:`1960`,title:`《度》`,type:`长篇小说`,note:`寄宿学校与多重视角，可见其创作脉络`},{year:`1962`,title:`《移动》`,type:`跨文体作品`,note:`美国旅行的地理拼贴，风格印记鲜明`},{year:`1963`,title:`《圣马可的描述》`,type:`跨文体作品`,note:`建筑、历史与叙事，值得细读`},{year:`1964`,title:`《现代随笔》`,type:`文论`,note:`小说形式与城市空间，可见其创作脉络`},{year:`1975`,title:`《梦的材料》`,type:`跨文体作品`,note:`梦境、记忆与文本生成，可见其创作脉络`}],position:`他把城市空间、建筑结构与时间表变成小说的组织原则，让叙事像地图一样展开，是新小说中形式最严密、也最具地理意识的一位。`,nobelYear:null},"a-878cae":{slug:`a-878cae`,birthDeath:`1913.10.10 — 2005.07.06`,nationality:`法国`,englishName:`CLAUDE SIMON`,movement:[`新小说`,`知觉叙事`,`历史记忆`],bio:[`生于马达加斯加塔那那利佛，童年在法国南部与加泰罗尼亚地区度过。二战中在骑兵部队作战并被俘，越狱后参加抵抗运动，战后经营葡萄园并开始写作。`,`早期《骗子》《居利弗》仍接近传统叙事，《春之祭》《风》《草》逐渐以感官印象与时间层叠取代情节；《弗兰德公路》以战败、逃亡与记忆的碎片写战争，确立其成熟风格。`,`《历史》《法萨卢斯战役》《农事诗》把家族史、西班牙内战与法国大革命叠印在同一知觉平面上，句子漫长而句法复杂；一九八五年获诺贝尔文学奖，晚年《刺槐》继续写记忆与衰老。`],controversies:[],works:[{year:`1945`,title:`《骗子》`,type:`长篇小说`,note:`早期传统叙事的尝试，风格印记鲜明`},{year:`1952`,title:`《居利弗》`,type:`长篇小说`,note:`战争记忆与形式转变，值得细读`},{year:`1957`,title:`《风》`,type:`长篇小说`,note:`感官印象与时间层叠，可见其创作脉络`},{year:`1958`,title:`《草》`,type:`长篇小说`,note:`土地、家族与记忆，风格印记鲜明`},{year:`1960`,title:`《弗兰德公路》`,type:`长篇小说`,note:`战败逃亡的知觉碎片，值得细读`},{year:`1967`,title:`《历史》`,type:`长篇小说`,note:`家族史与帝国记忆，可见其创作脉络`},{year:`1969`,title:`《法萨卢斯战役》`,type:`长篇小说`,note:`古代战争与现代记忆，风格印记鲜明`},{year:`1981`,title:`《农事诗》`,type:`长篇小说`,note:`家族、革命与战争叠印，风格印记鲜明`},{year:`1989`,title:`《刺槐》`,type:`长篇小说`,note:`记忆、衰老与历史回响，值得细读`}],position:`他把战争、家族史与知觉印象压进同一绵长句法，让时间在叙述中反复折返，是新小说中最具历史重量与感官密度的作家，也是该流派唯一的诺奖得主。`,positionSource:`— 诺贝尔文学奖授奖辞`,nobelYear:1985},"a-866547":{slug:`a-866547`,birthDeath:`1936.03.07 — 1982.03.03`,nationality:`法国`,englishName:`GEORGES PEREC`,movement:[`潜在文学工场`,`形式约束写作`,`自传性虚构`],bio:[`生于巴黎的波兰犹太移民家庭，父亲在二战中阵亡，母亲死于奥斯维辛。战后由亲戚抚养，攻读社会学，早年以评论与纪录片工作维生，身份与缺失成为其写作的隐秘核心。`,`《物》以消费社会的年轻夫妇写欲望的空洞，《沉睡的人》以第二人称写城市中的退缩；《消失》全书不用字母 e，以极端的限制性写作把失踪与哀悼编码进语言。`,`《W或苦难的记忆》在虚构岛屿与自传碎片之间交替，《人生拼图版》以巴黎公寓的剖面图组织九十九个章节，把器物、故事与清单拼成一座建筑；他四十五岁因肺癌去世，潜在文学工场因此失去核心成员。`],controversies:[],works:[{year:`1965`,title:`《物》`,type:`长篇小说`,note:`消费社会与欲望的空洞`},{year:`1967`,title:`《沉睡的人》`,type:`长篇小说`,note:`第二人称的城市退缩，值得细读`},{year:`1969`,title:`《消失》`,type:`长篇小说`,note:`全书不用字母 e 的限制，可见其创作脉络`},{year:`1972`,title:`《重现》`,type:`长篇小说`,note:`限制性写作的再次实验`},{year:`1975`,title:`《W或苦难的记忆》`,type:`跨文体作品`,note:`虚构岛屿与自传碎片，可见其创作脉络`},{year:`1978`,title:`《人生拼图版》`,type:`长篇小说`,note:`巴黎公寓剖面的拼图，风格印记鲜明`},{year:`1978`,title:`《我记得》`,type:`随笔集`,note:`集体记忆的碎片清单，值得细读`}],position:`他把限制、清单与建筑结构变成小说的生成规则，用形式约束承载失踪、记忆与大屠杀的沉默，是潜在文学工场最富想象力的实践者。`,nobelYear:null},"a-91163e":{slug:`a-91163e`,birthDeath:`1907.09.22 — 2003.02.20`,nationality:`法国`,englishName:`MAURICE BLANCHOT`,movement:[`法国思想`,`文学空间`,`极限写作`],bio:[`生于索恩-卢瓦尔省坎，攻读哲学与德语，长期以文学评论为业。三十年代曾为右翼报刊撰稿，这段经历在战后被重新审视，成为其思想传记中难以回避的阴影。`,`《黑暗的托马斯》以无名叙述者写死亡与语言的边界，《阿米纳达布》《最高者》继续构造没有心理深度的抽象寓言；他的小说拒绝情节与人物，接近哲学寓言。`,`《文学空间》把写作定义为对死亡的接近，《未来之书》《无尽的交谈》以片段与重复展开语言、他者与沉默；他极少公开露面，却深刻影响福柯、德里达与法国战后文学理论。`],controversies:[{tag:`战时履历争议`,content:`他三十年代为右翼与反犹报刊撰稿的经历在晚年与身后被披露，引发关于其政治立场、战后沉默与思想责任的长期争论。`}],works:[{year:`1941`,title:`《黑暗的托马斯》`,type:`长篇小说`,note:`死亡与语言边界的寓言`},{year:`1942`,title:`《阿米纳达布》`,type:`长篇小说`,note:`没有心理深度的叙事，可见其创作脉络`},{year:`1948`,title:`《最高者》`,type:`长篇小说`,note:`权力、疾病与沉默，风格印记鲜明`},{year:`1948`,title:`《死亡时刻》`,type:`长篇小说`,note:`死亡、爱情与叙事边界书写`},{year:`1949`,title:`《洛特雷阿蒙与萨德》`,type:`文论`,note:`极限写作的早期研究，值得细读`},{year:`1955`,title:`《文学空间》`,type:`文论`,note:`写作作为对死亡的接近`},{year:`1959`,title:`《未来之书》`,type:`文论`,note:`语言、时间与文学未来，风格印记鲜明`},{year:`1969`,title:`《无尽的交谈》`,type:`文论`,note:`片段、他者与思想对话，值得细读`},{year:`1980`,title:`《灾难的写作》`,type:`文论`,note:`灾难、沉默与书写极限，可见其创作脉络`}],position:`他把文学理解为对沉默与他者的无尽接近，用片段、重复和悖论写作，深刻塑造了法国战后文学理论与现代主义之后的写作伦理。`,nobelYear:null},"a-473f09":{slug:`a-473f09`,birthDeath:`1945.07.30 —`,nationality:`法国`,englishName:`PATRICK MODIANO`,movement:[`记忆小说`,`战后法国`,`身份追寻`],bio:[`生于巴黎西郊布洛涅-比扬古，父亲有意大利犹太血统，母亲是比利时演员，二人在占领时期相识。家庭对战争年代的含糊叙述，成为他日后反复追问的身份空洞。`,`《星形广场》以犹太身份的荒诞冒险闯入文坛，《夜巡》《环城大道》继续在占领时期与巴黎边缘写背叛；电影剧本《拉孔布·吕西安》把一个投靠盖世太保的少年写得暧昧难判。`,`《暗店街》以失忆侦探寻找过去获龚古尔奖，《朵拉·布吕德》以真实犹太少女的遣送记录拼合档案与记忆；二〇一四年获诺贝尔文学奖，作品始终围绕遗忘、追踪与巴黎的旧街。`],controversies:[],works:[{year:`1968`,title:`《星形广场》`,type:`长篇小说`,note:`犹太身份的荒诞冒险，可见其创作脉络`},{year:`1969`,title:`《夜巡》`,type:`长篇小说`,note:`占领时期的背叛与暧昧`},{year:`1972`,title:`《环城大道》`,type:`长篇小说`,note:`巴黎边缘的父子追踪，风格印记鲜明`},{year:`1974`,title:`《拉孔布·吕西安》`,type:`电影剧本`,note:`投敌少年的道德暧昧，值得细读`},{year:`1978`,title:`《暗店街》`,type:`长篇小说`,note:`失忆侦探寻找过去，可见其创作脉络`},{year:`1997`,title:`《朵拉·布吕德》`,type:`跨文体作品`,note:`犹太少女的遣送档案，风格印记鲜明`},{year:`2001`,title:`《小首饰》`,type:`长篇小说`,note:`童年与失踪的母亲，值得细读`},{year:`2007`,title:`《青春咖啡馆》`,type:`长篇小说`,note:`巴黎咖啡馆中的逃离者`},{year:`2014`,title:`《为了不迷失在街区》`,type:`长篇小说`,note:`记忆、地址与身份，可见其创作脉络`}],position:`他把占领时期的巴黎写成一座记忆的迷宫，用侦探式追踪与重复的街名处理遗忘与身份，是法国当代最坚持同一主题、却每次都能变奏的作家。`,positionSource:`— 诺贝尔文学奖授奖辞`,nobelYear:2014},"a-a48458":{slug:`a-a48458`,birthDeath:`1940.09.01 —`,nationality:`法国`,englishName:`ANNIE ERNAUX`,movement:[`自传体社会学`,`女性书写`,`平白文体`],bio:[`生于诺曼底利勒博纳，父母在伊沃托经营咖啡馆与杂货店。先后在鲁昂与波尔多攻读文学，成为中学教师，阶级跨越的羞耻与背叛感成为她写作的起点。`,`《空衣柜》以愤怒的独白写堕胎与阶层，《位置》以平白句子写父亲的工人一生，《一个女人的故事》写母亲之死；她拒绝抒情修饰，用社会学式的精确记录个人经验。`,`《简单的激情》《羞耻》《事件》继续把欲望、堕胎与阶级记忆置于公共目光之下，《悠悠岁月》以无人称自传写一代法国人的集体记忆；二〇二二年获诺贝尔文学奖。`],controversies:[],works:[{year:`1974`,title:`《空衣柜》`,type:`长篇小说`,note:`堕胎、阶层与愤怒独白，风格印记鲜明`},{year:`1977`,title:`《他们说的或没什么》`,type:`长篇小说`,note:`少女欲望与语言，风格印记鲜明`},{year:`1983`,title:`《位置》`,type:`自传`,note:`父亲工人一生的平白书写`},{year:`1987`,title:`《一个女人的故事》`,type:`自传`,note:`母亲之死与阶级记忆，值得细读`},{year:`1991`,title:`《简单的激情》`,type:`自传`,note:`婚外情欲的冷静记录，可见其创作脉络`},{year:`1993`,title:`《外面的日记》`,type:`日记`,note:`日常观察与社会空间，风格印记鲜明`},{year:`1997`,title:`《羞耻》`,type:`自传`,note:`少女时代的阶级创伤，值得细读`},{year:`2000`,title:`《事件》`,type:`自传`,note:`非法堕胎的身体经验，可见其创作脉络`},{year:`2008`,title:`《悠悠岁月》`,type:`自传`,note:`无人称的一代集体记忆`},{year:`2016`,title:`《女孩的记忆》`,type:`自传`,note:`青年时代的欲望与写作`}],position:`她把个人记忆写成阶级与性别的社会档案，用平白、精确的句子拒绝文学修饰，使自传成为理解法国战后社会流动与女性经验的重要文本。`,positionSource:`— 诺贝尔文学奖授奖辞`,nobelYear:2022},"a-da5d53":{slug:`a-da5d53`,birthDeath:`1956.02.26 —`,nationality:`法国`,englishName:`MICHEL HOUELLEBECQ`,movement:[`后现代现实主义`,`反乌托邦`,`社会讽刺`],bio:[`生于印度洋留尼汪岛，幼年由祖母抚养，在阿尔及利亚与法国本土之间迁徙。受过农艺训练，做过计算机管理员，早年写诗与文学评论，九十年代转向小说。`,`《斗争领域的延伸》以性市场与职场写自由主义的疲惫，《基本粒子》用两个同母异父兄弟的生物学与性爱史宣告一个时代的终结，引发巨大争论并成为畅销书。`,`《平台》把旅游、性观光与恐怖主义并置，《地图与疆域》以画家与自身之死写艺术市场，获龚古尔奖；《屈服》设想穆斯林政党执政的法国，《血清素》《毁灭》继续写中年抑郁与文明衰败。`],controversies:[{tag:`厌女与政治争议`,content:`他的小说被指厌女、对伊斯兰教作挑衅性描绘，《屈服》出版后更引发法国公共论战，支持者称其社会诊断尖锐，批评者指其放大偏见。`}],works:[{year:`1994`,title:`《斗争领域的延伸》`,type:`长篇小说`,note:`性市场与职场疲惫，风格印记鲜明`},{year:`1998`,title:`《基本粒子》`,type:`长篇小说`,note:`两兄弟的性与时代终结`},{year:`2001`,title:`《平台》`,type:`长篇小说`,note:`旅游、性观光与恐怖主义`},{year:`2005`,title:`《一个岛的可能性》`,type:`长篇小说`,note:`克隆人与爱情的反乌托邦`},{year:`2010`,title:`《地图与疆域》`,type:`长篇小说`,note:`画家、艺术市场与自身之死`},{year:`2015`,title:`《屈服》`,type:`长篇小说`,note:`穆斯林政党执政的法国`},{year:`2019`,title:`《血清素》`,type:`长篇小说`,note:`中年抑郁与农业危机，值得细读`},{year:`2022`,title:`《毁灭》`,type:`长篇小说`,note:`文明衰败与家庭死亡，可见其创作脉络`}],position:`他以冷酷的社会解剖与挑衅性政治想象写晚期资本主义的性、孤独与文明疲劳，是当代法国最具争议也最被广泛阅读的小说家之一。`,nobelYear:null},"a-715e97":{slug:`a-715e97`,birthDeath:`1940.04.13 —`,nationality:`法国/毛里求斯裔`,englishName:`J. M. G. LE CLEZIO`,movement:[`新寓言`,`后殖民书写`,`感官叙事`],bio:[`生于尼斯，家族源自毛里求斯，童年在二战疏散与非洲旅行中度过。在布里斯托与艾克斯攻读文学，早年以《诉讼笔录》获勒诺多奖，被归入新小说的年轻一代。`,`《发烧》《洪水》《大地》以感官、城市与灾难写现代人的眩晕，《战争》则把消费社会写成一场持续的战争；他很快脱离新小说，转向更抒情、更关注非西方文明的叙事。`,`《沙漠》以撒哈拉少女与移民写殖民与自然，《寻金者》《奥尼沙》回望毛里求斯与非洲，《黄金鱼》写被贩卖的女孩；二〇〇八年获诺贝尔文学奖，旅行随笔与儿童文学同样丰富。`],controversies:[],works:[{year:`1963`,title:`《诉讼笔录》`,type:`长篇小说`,note:`勒诺多奖的早期实验，风格印记鲜明`},{year:`1965`,title:`《发烧》`,type:`短篇小说集`,note:`感官与城市的眩晕，值得细读`},{year:`1966`,title:`《洪水》`,type:`长篇小说`,note:`灾难、城市与现代焦虑，值得细读`},{year:`1967`,title:`《大地》`,type:`长篇小说`,note:`感官碎片与文明批判，可见其创作脉络`},{year:`1970`,title:`《战争》`,type:`长篇小说`,note:`消费社会作为持续战争`},{year:`1980`,title:`《沙漠》`,type:`长篇小说`,note:`撒哈拉少女与移民，风格印记鲜明`},{year:`1985`,title:`《寻金者》`,type:`长篇小说`,note:`毛里求斯与失落的父亲`},{year:`1991`,title:`《奥尼沙》`,type:`长篇小说`,note:`非洲殖民地的童年记忆`},{year:`1997`,title:`《黄金鱼》`,type:`长篇小说`,note:`被贩卖女孩的流浪，值得细读`},{year:`2003`,title:`《革命》`,type:`长篇小说`,note:`家族史与二十世纪革命`}],position:`他以感官化的抒情笔法写殖民、迁徙与自然，把非西方文明的经验带入法国小说，是当代法语文学中最具世界主义视野的作家之一。`,positionSource:`— 诺贝尔文学奖授奖辞`,nobelYear:2008},"a-5bdea0":{slug:`a-5bdea0`,birthDeath:`1942.12.06 —`,nationality:`奥地利`,englishName:`PETER HANDKE`,movement:[`新主体性`,`语言实验`,`剧场写作`],bio:[`生于奥地利克恩顿州格里芬，母亲是斯洛文尼亚裔，家庭经历战争与贫困。格拉茨大学攻读法律，六十年代以语言实验剧作震动德语剧坛，成为四七社最年轻的成员之一。`,`《骂观众》彻底取消情节与角色，直接对观众说话，《卡斯帕》以语言学习过程写暴力规训；《守门员面对罚点球时的焦虑》则以日常细节写犯罪者的感知断裂。`,`《无欲的悲歌》以母亲之死写女性命运，《缓慢的归乡》转向自然与自我观察；他后期写游记、日记与长篇散文，二〇一九年获诺贝尔文学奖，其南斯拉夫立场同时引发巨大争议。`],controversies:[{tag:`南斯拉夫立场争议`,content:`一九九〇年代起他公开为塞尔维亚辩护、质疑西方对南斯拉夫战争的叙述，并出席米洛舍维奇葬礼，二〇一九年获诺奖时引发广泛抗议与评委会辩护。`}],works:[{year:`1966`,title:`《大黄蜂》`,type:`长篇小说`,note:`早期语言实验与感知，可见其创作脉络`},{year:`1966`,title:`《骂观众》`,type:`戏剧`,note:`取消情节的观众挑衅，风格印记鲜明`},{year:`1968`,title:`《卡斯帕》`,type:`戏剧`,note:`语言学习与暴力规训，值得细读`},{year:`1970`,title:`《守门员面对罚点球时的焦虑》`,type:`长篇小说`,note:`日常细节与感知断裂，可见其创作脉络`},{year:`1972`,title:`《无欲的悲歌》`,type:`中篇小说`,note:`母亲之死与女性命运，风格印记鲜明`},{year:`1975`,title:`《真实感受的时刻》`,type:`长篇小说`,note:`自我观察与瞬间经验，值得细读`},{year:`1976`,title:`《左撇子女人》`,type:`长篇小说`,note:`女性独立与婚姻逃离，可见其创作脉络`},{year:`1979`,title:`《缓慢的归乡》`,type:`长篇小说`,note:`自然、地理与自我修复，可见其创作脉络`},{year:`1981`,title:`《关于乡村》`,type:`戏剧`,note:`语言、土地与共同体，风格印记鲜明`},{year:`1994`,title:`《我在无人湾的一年》`,type:`长篇小说`,note:`隐居、写作与季节，值得细读`}],position:`他把语言视为规训与解放的双重装置，从反戏剧到缓慢的散文体，持续实验感知如何被书写；其文学成就与政治争议同样构成二十世纪后期德语文学的核心话题。`,positionSource:`— 诺贝尔文学奖授奖辞`,nobelYear:2019},"a-542b26":{slug:`a-542b26`,birthDeath:`1946.10.20 —`,nationality:`奥地利`,englishName:`ELFRIEDE JELINEK`,movement:[`女性主义写作`,`语言批判`,`音乐性散文`],bio:[`生于奥地利米尔茨楚施拉格，在维也纳长大，父亲是化学家，母亲出身富裕家庭。自幼学习钢琴与管风琴，音乐训练深刻影响其句法与节奏；后攻读戏剧与艺术史。`,`《莉莎的影子》以少女视角写家庭暴力，《我们是诱鸟，宝贝》以漫画、广告与流行文化拼贴消费社会；《钢琴教师》以母女关系与性压抑写权力如何内化为欲望。`,`《情欲》以露骨性描写拆解男性凝视，《死者的孩子们》以僵尸与历史写奥地利对纳粹过去的遗忘；二〇〇四年获诺贝尔文学奖，其作品与公开言论长期与奥地利右翼政治冲突。`],controversies:[{tag:`与奥地利右翼论战`,content:`二〇〇〇年奥地利自由党入阁时她公开抗议，作品与言论屡遭右翼攻击；获诺奖后，围绕其暴力与色情描写的争论再次升温。`}],works:[{year:`1967`,title:`《莉莎的影子》`,type:`诗集`,note:`少女视角与家庭暴力，可见其创作脉络`},{year:`1970`,title:`《我们是诱鸟，宝贝》`,type:`长篇小说`,note:`流行文化与消费社会拼贴`},{year:`1972`,title:`《米夏埃尔》`,type:`长篇小说`,note:`青少年与媒体暴力，风格印记鲜明`},{year:`1983`,title:`《钢琴教师》`,type:`长篇小说`,note:`母女关系与性压抑，值得细读`},{year:`1989`,title:`《情欲》`,type:`长篇小说`,note:`露骨性描写与男性凝视`},{year:`1995`,title:`《死者的孩子们》`,type:`长篇小说`,note:`僵尸与奥地利历史遗忘`},{year:`2000`,title:`《贪婪》`,type:`长篇小说`,note:`男性欲望与暴力，可见其创作脉络`},{year:`2007`,title:`《嫉妒》`,type:`长篇小说`,note:`性、权力与语言游戏，风格印记鲜明`},{year:`2013`,title:`《受托者》`,type:`戏剧`,note:`难民与欧洲的道德伪善`}],position:`她用音乐性的语言与露骨的暴力拆解性别权力和奥地利的历史遗忘，把文学变成冒犯性的政治行动，是战后德语文学中最不肯妥协的声音。`,positionSource:`— 诺贝尔文学奖授奖辞`,nobelYear:2004},"a-27c34d":{slug:`a-27c34d`,birthDeath:`1931.02.09 — 1989.02.12`,nationality:`奥地利`,englishName:`THOMAS BERNHARD`,movement:[`奥地利批判文学`,`语言音乐性`,`独白体`],bio:[`生于荷兰海尔伦，母亲是奥地利作家，父亲是荷兰商人，童年在寄宿学校与祖父母之间辗转。少年患肺结核，长期住院，后在萨尔茨堡学习音乐与戏剧，又转读法律。`,`《霜》以乡村医生的孤独写疾病与缓慢死亡，《扰乱》以精神病院与村庄写语言与理性的失控，《石灰厂》以封闭空间的疯狂独白把德语句法推向重复与极限。`,`《修正》以自杀者的遗稿写思想与自然的对抗，《维特根斯坦的侄子》混合友谊与疯狂，《伐木》以艺术家晚宴讽刺奥地利文化界；《英雄广场》首演引发全国争论，他在遗嘱中禁止作品在奥地利上演。`],controversies:[{tag:`英雄广场争议`,content:`一九八八年剧作《英雄广场》在维也纳首演，借犹太教授之口批判奥地利的反犹与自满，引发全国性论战；他随后禁止作品在奥地利出版与上演。`}],works:[{year:`1963`,title:`《霜》`,type:`长篇小说`,note:`乡村医生的孤独与死亡`},{year:`1967`,title:`《扰乱》`,type:`长篇小说`,note:`精神病院与语言的失控`},{year:`1970`,title:`《石灰厂》`,type:`长篇小说`,note:`封闭空间的疯狂独白，值得细读`},{year:`1975`,title:`《修正》`,type:`长篇小说`,note:`遗稿、思想与自然的对抗`},{year:`1978`,title:`《是的》`,type:`长篇小说`,note:`孤立与自我毁灭，可见其创作脉络`},{year:`1980`,title:`《廉价食客》`,type:`短篇小说`,note:`边缘人的观察与嘲讽，风格印记鲜明`},{year:`1982`,title:`《维特根斯坦的侄子》`,type:`中篇小说`,note:`友谊、疯狂与音乐，值得细读`},{year:`1983`,title:`《失败者》`,type:`长篇小说`,note:`钢琴天才的放弃，可见其创作脉络`},{year:`1984`,title:`《伐木》`,type:`长篇小说`,note:`艺术家晚宴与文化讽刺`},{year:`1986`,title:`《灭绝》`,type:`长篇小说`,note:`家族与奥地利的清算，风格印记鲜明`}],position:`他用重复、夸张与音乐性的独白把奥地利写成一座充满虚伪与自杀冲动的舞台，语言既是控诉也是自我消耗，是战后德语文学最激烈的批判者。`,nobelYear:null},"a-142b37":{slug:`a-142b37`,birthDeath:`1922.11.16 — 2010.06.18`,nationality:`葡萄牙`,englishName:`JOSE SARAMAGO`,movement:[`魔幻寓言`,`政治寓言`,`伊比利亚叙事`],bio:[`生于葡萄牙阿辛哈加贫苦农家，随家迁居里斯本，做过机械工、绘图员与出版社编辑，长期以翻译维生。文学创作起步较晚，直到六十岁后才获得国际声誉。`,`《从地面升起》以无地农民的口述史写阿连特茹，《修道院纪事》把十八世纪修道院与飞行器并置，《里卡多·雷伊斯死亡之年》让佩索阿的异名者回到里斯本。`,`《耶稣基督福音》因重新塑造耶稣与抹大拉的关系遭教会抵制，《失明症漫记》以集体失明写文明崩溃，《所有名字》与《洞穴》继续寓言化官僚社会；一九九八年获诺贝尔文学奖，晚年移居兰萨罗特岛。`],controversies:[{tag:`教会与奖项冲突`,content:`《耶稣基督福音》一九九一年被葡萄牙政府撤销欧洲文学奖提名，天主教会批评其亵渎，萨拉马戈因此移居西班牙加那利群岛。`}],works:[{year:`1980`,title:`《从地面升起》`,type:`长篇小说`,note:`无地农民的口述史，值得细读`},{year:`1982`,title:`《修道院纪事》`,type:`长篇小说`,note:`修道院、飞行器与爱情，风格印记鲜明`},{year:`1984`,title:`《里卡多·雷伊斯死亡之年》`,type:`长篇小说`,note:`佩索阿异名者的归来，可见其创作脉络`},{year:`1986`,title:`《石筏》`,type:`长篇小说`,note:`伊比利亚半岛漂流寓言`},{year:`1991`,title:`《耶稣基督福音》`,type:`长篇小说`,note:`福音书的人性化重写，风格印记鲜明`},{year:`1995`,title:`《失明症漫记》`,type:`长篇小说`,note:`集体失明与文明崩溃，值得细读`},{year:`1997`,title:`《所有名字》`,type:`长篇小说`,note:`档案、名字与孤独，可见其创作脉络`},{year:`2000`,title:`《洞穴》`,type:`长篇小说`,note:`消费社会与手艺人的消失`},{year:`2004`,title:`《复明症漫记》`,type:`长篇小说`,note:`重见之后的政治荒诞寓言`},{year:`2005`,title:`《死亡的间歇》`,type:`长篇小说`,note:`死亡罢工的黑色寓言，风格印记鲜明`}],position:`他用寓言、反讽与长句把伊比利亚的专制遗产、官僚理性与人类盲目写成普遍政治神话，是二十世纪末最受国际阅读的葡萄牙作家。`,positionSource:`— 诺贝尔文学奖授奖辞`,nobelYear:1998},"a-5414f9":{slug:`a-5414f9`,birthDeath:`1891.05.23 — 1974.07.11`,nationality:`瑞典`,englishName:`PAR LAGERKVIST`,movement:[`表现主义`,`宗教寓言`,`现代主义`],bio:[`生于瑞典斯莫兰地区韦克舍，家庭信奉严格的路德宗，宗教氛围与对信仰的怀疑同时构成其精神底色。乌普萨拉大学求学期间转向艺术与文学，早期诗作带有表现主义色彩。`,`《苦闷》以破碎意象写现代人的恐惧，剧作《复活的人》等把表现主义舞台推向极端；他长期以戏剧探索信仰、权力与死亡，是瑞典现代主义的核心人物之一。`,`《侏儒》以宫廷侏儒的日记写人性之恶，《巴拉巴》以圣经中获释的盗贼追问信仰与自由，《女先知》继续处理神话与启示；一九五一年获诺贝尔文学奖，晚年作品趋于静默的宗教寓言。`],controversies:[],works:[{year:`1916`,title:`《苦闷》`,type:`诗集`,note:`表现主义的恐惧与破碎`},{year:`1919`,title:`《混沌》`,type:`诗集`,note:`战争与信仰危机，值得细读`},{year:`1944`,title:`《侏儒》`,type:`长篇小说`,note:`宫廷侏儒日记中的人性恶`},{year:`1950`,title:`《巴拉巴》`,type:`长篇小说`,note:`获释盗贼的信仰追问，可见其创作脉络`},{year:`1956`,title:`《女先知》`,type:`长篇小说`,note:`神话、预言与信仰，风格印记鲜明`},{year:`1960`,title:`《阿哈随鲁之死》`,type:`长篇小说`,note:`流浪者传说与死亡，值得细读`},{year:`1962`,title:`《海上的朝圣者》`,type:`长篇小说`,note:`旅程与宗教寓言，可见其创作脉络`},{year:`1964`,title:`《圣地》`,type:`长篇小说`,note:`晚期信仰与救赎主题，风格印记鲜明`}],position:`他把表现主义的焦虑与宗教寓言结合，持续追问信仰在暴力与荒诞世界中的可能，是瑞典现代主义从先锋转向哲思的重要桥梁。`,positionSource:`— 诺贝尔文学奖授奖辞`,nobelYear:1951},"a-524a4f":{slug:`a-524a4f`,birthDeath:`1931.04.15 — 2015.03.26`,nationality:`瑞典`,englishName:`TOMAS TRANSTROMER`,movement:[`瑞典现代主义`,`意象诗`,`超现实主义`],bio:[`生于斯德哥尔摩，父母离异后由母亲抚养，童年在城市与群岛之间度过。乌普萨拉大学攻读心理学，长期在少年监狱与劳动机构任心理医生，职业经验使其诗作关注边缘与梦。`,`《十七首诗》以凝练意象与音乐性确立独特风格，《途中的秘密》《半完成的天空》把自然、城市与梦境压缩进短句，《波罗的海》则以家族史与岛屿写记忆与死亡。`,`一九九〇年中风后右半身瘫痪，语言能力受损，仍以左手写作并出版《悲伤的贡多拉》《巨大的谜》；二〇一一年获诺贝尔文学奖，其诗被译成多种语言，影响遍及世界。`],controversies:[],works:[{year:`1954`,title:`《十七首诗》`,type:`诗集`,note:`凝练意象的成名作，值得细读`},{year:`1958`,title:`《途中的秘密》`,type:`诗集`,note:`自然、城市与梦境，可见其创作脉络`},{year:`1962`,title:`《半完成的天空》`,type:`诗集`,note:`短句中的超现实风景，风格印记鲜明`},{year:`1973`,title:`《小路》`,type:`诗集`,note:`旅行与内心地理，值得细读`},{year:`1974`,title:`《波罗的海》`,type:`诗集`,note:`家族史与岛屿记忆，可见其创作脉络`},{year:`1978`,title:`《真理的屏障》`,type:`诗集`,note:`语言、边界与沉默，风格印记鲜明`},{year:`1983`,title:`《狂野的广场》`,type:`诗集`,note:`公共空间与私人恐惧，值得细读`},{year:`1989`,title:`《为生者与死者》`,type:`诗集`,note:`死亡、记忆与音乐，可见其创作脉络`},{year:`1996`,title:`《悲伤的贡多拉》`,type:`诗集`,note:`中风后的短诗与哀歌，风格印记鲜明`},{year:`2004`,title:`《巨大的谜》`,type:`诗集`,note:`晚期极短诗与谜语，值得细读`}],position:`他用极简意象与严密音乐性把日常经验提升为对存在、历史与死亡的凝视，是二十世纪后半叶最重要的欧洲抒情诗人之一。`,positionSource:`— 诺贝尔文学奖授奖辞`,nobelYear:2011},"a-2eef9f":{slug:`a-2eef9f`,birthDeath:`1959.09.25 —`,nationality:`挪威`,englishName:`JON FOSSE`,movement:[`新挪威语写作`,`极简主义`,`静默戏剧`],bio:[`生于挪威西海岸豪格松，成长于哈当厄尔峡湾一带，以新挪威语写作。就读卑尔根大学，研习文学与社会学，早年做过教师与记者，八十年代以小说与诗集进入文坛。`,`《红，黑》以短句与重复写音乐与死亡，《船屋》以峡湾与家族写孤独；九十年代转向戏剧，《有人将至》《名字》以停顿、重复与沉默构造紧张，成为欧洲舞台常演的当代剧作。`,`《三部曲》以梦游般的叙事写一对年轻恋人的逃亡，《七部曲》以同一人物的不同时间线与祈祷展开长篇独白；二〇二三年获诺贝尔文学奖，被称为新挪威语文学最重要的声音。`],controversies:[],works:[{year:`1983`,title:`《红，黑》`,type:`长篇小说`,note:`短句、重复与音乐，可见其创作脉络`},{year:`1985`,title:`《关闭的吉他》`,type:`长篇小说`,note:`孤独与家庭断裂，风格印记鲜明`},{year:`1989`,title:`《船屋》`,type:`长篇小说`,note:`峡湾、家族与回忆，值得细读`},{year:`1995`,title:`《名字》`,type:`戏剧`,note:`重复与沉默的舞台，可见其创作脉络`},{year:`1996`,title:`《有人将至》`,type:`戏剧`,note:`等待与威胁的极简剧，风格印记鲜明`},{year:`1999`,title:`《秋之梦》`,type:`戏剧`,note:`墓地、记忆与重逢，值得细读`},{year:`2001`,title:`《死亡变奏》`,type:`戏剧`,note:`死亡与家庭对峙，可见其创作脉络`},{year:`2014`,title:`《三部曲》`,type:`长篇小说`,note:`梦游叙事中的逃亡恋人`},{year:`2019`,title:`《七部曲》`,type:`长篇小说`,note:`同一人物的时间与祈祷`}],position:`他用重复、停顿与近乎无声的句子写孤独、信仰与死亡，把新挪威语的口语节奏带上世界舞台，是当代欧洲戏剧与小说中最静默也最持久的声音。`,positionSource:`— 诺贝尔文学奖授奖辞`,nobelYear:2023},"a-830bbf":{slug:`a-830bbf`,birthDeath:`约1943 —`,nationality:`意大利`,englishName:`ELENA FERRANTE`,movement:[`那不勒斯小说`,`女性书写`,`匿名写作`],bio:[`以笔名发表作品，真实身份至今未公开。作者自述生于那不勒斯，童年在战后贫困与家族缝纫作坊的噪声中度过，这座城市的方言、暴力与阶层裂缝贯穿其全部小说。`,`《讨厌的爱》以母亲之死写那不勒斯的性、谎言与权力，《被遗弃的日子》以婚姻破裂写中年女性崩溃，《迷失的女儿》把母职的内疚与逃离写得毫不宽容而尖锐。`,`《我的天才女友》四部曲以两个那不勒斯女孩的一生写友谊、教育与社会流动，成为全球畅销现象；《成年人的谎言生活》继续解剖阶层与身体，作者始终拒绝公开身份，使匿名本身成为作品的一部分。`],controversies:[],works:[{year:`1992`,title:`《讨厌的爱》`,type:`长篇小说`,note:`母亲之死与那不勒斯，风格印记鲜明`},{year:`2002`,title:`《被遗弃的日子》`,type:`长篇小说`,note:`婚姻破裂与女性崩溃，值得细读`},{year:`2006`,title:`《迷失的女儿》`,type:`长篇小说`,note:`母职的内疚与逃离，可见其创作脉络`},{year:`2011`,title:`《我的天才女友》`,type:`长篇小说`,note:`两个女孩的友谊与街区`},{year:`2012`,title:`《新名字的故事》`,type:`长篇小说`,note:`婚姻、教育与阶层流动，值得细读`},{year:`2013`,title:`《离开与留下的人》`,type:`长篇小说`,note:`城市暴力与政治承诺，风格印记鲜明`},{year:`2014`,title:`《失踪孩子的故事》`,type:`长篇小说`,note:`四部曲终卷的失落，值得细读`},{year:`2019`,title:`《成年人的谎言生活》`,type:`长篇小说`,note:`阶层、身体与谎言，可见其创作脉络`},{year:`2021`,title:`《边缘与写作》`,type:`随笔集`,note:`关于写作与阅读的讲稿`}],position:`她以匿名写作把注意力完全交给那不勒斯的女性经验，用友谊、阶层与母职的长期叙事构造当代欧洲最广泛的阅读现象，也重新定义作者与作品的关系。`,nobelYear:null},"a-c54522":{slug:`a-c54522`,birthDeath:`1952.06.07 —`,nationality:`土耳其`,englishName:`ORHAN PAMUK`,movement:[`后现代小说`,`东西方叙事`,`伊斯坦布尔书写`],bio:[`生于伊斯坦布尔一个中产家庭，少年习画，后入伊斯坦布尔理工大学攻读建筑，转读新闻。长期在纽约与伊斯坦布尔之间生活，早期小说以家族史与城市记忆为轴。`,`《杰夫代特先生与他的儿子们》以三代家族写土耳其现代化，《寂静的房子》用多视角写小镇记忆，《白色城堡》以东西方替身写身份；《黑书》把伊斯坦布尔的街巷写成迷宫。`,`《我的名字叫红》以细密画与谋杀案写观看与风格，《雪》处理政治伊斯兰与头巾问题，《伊斯坦布尔》以个人回忆写城市忧郁；二〇〇六年获诺贝尔文学奖，近年《瘟疫之夜》转向历史寓言。`],controversies:[{tag:`亚美尼亚言论审判`,content:`二〇〇五年他公开谈及奥斯曼时期对亚美尼亚人与库尔德人的杀戮，被以侮辱土耳其国民性起诉，后在国际压力下撤诉，事件加剧其与民族主义者的冲突。`}],works:[{year:`1982`,title:`《杰夫代特先生与他的儿子们》`,type:`长篇小说`,note:`三代家族与土耳其现代化`},{year:`1983`,title:`《寂静的房子》`,type:`长篇小说`,note:`多视角的小镇记忆，风格印记鲜明`},{year:`1985`,title:`《白色城堡》`,type:`长篇小说`,note:`东西方替身与身份，值得细读`},{year:`1990`,title:`《黑书》`,type:`长篇小说`,note:`伊斯坦布尔街巷的迷宫`},{year:`1994`,title:`《新人生》`,type:`长篇小说`,note:`阅读、旅行与身份转变，可见其创作脉络`},{year:`1998`,title:`《我的名字叫红》`,type:`长篇小说`,note:`细密画、谋杀与观看，可见其创作脉络`},{year:`2002`,title:`《雪》`,type:`长篇小说`,note:`政治伊斯兰与头巾，风格印记鲜明`},{year:`2003`,title:`《伊斯坦布尔》`,type:`回忆录`,note:`城市忧郁与个人记忆，值得细读`},{year:`2008`,title:`《纯真博物馆》`,type:`长篇小说`,note:`爱情、收藏与时间，可见其创作脉络`},{year:`2021`,title:`《瘟疫之夜》`,type:`长篇小说`,note:`奥斯曼岛屿的瘟疫寓言`}],position:`他把东西方之间的身份焦虑、细密画的观看传统与伊斯坦布尔的忧郁写进多声部小说，既是最国际化的土耳其作家，也是最坚持地方记忆的叙事者。`,positionSource:`— 诺贝尔文学奖授奖辞`,nobelYear:2006}};export{e as g6};